// Visual explainers for the Computer Architecture & OS roadmap. Schema: CONTRIBUTING.md → "Visuals".
'use strict';

// ===== Module 1: Computer Fundamentals =====================================

registerDiagram({
  id: 'ca-fetch-decode-execute',
  roadmap: 'computer-architecture', module: 1, topic: 'Von Neumann Architecture & the Fetch-Decode-Execute Cycle',
  kind: 'graph',
  title: 'One instruction through a von Neumann machine',
  desc: 'Code and data live in the same memory and travel over the same path to the CPU. Follow add rax, [rbx] through fetch, decode, execute and write back, then see why that shared path became the bottleneck.',
  groups: [
    { id: 'cpu', label: 'CPU core', x: 0, y: 0, w: 3, h: 3, color: 'blue' },
    { id: 'ram', label: 'Main memory (DRAM)', x: 6, y: 0, w: 1, h: 3, color: 'teal' },
  ],
  nodes: [
    { id: 'pc', label: 'Program counter', sub: 'RIP = 0x401000', x: 0, y: 0, color: 'purple', info: 'Holds the address of the next instruction. Fetch advances it by the instruction length (x86 instructions are 1 to 15 bytes; ARM64 always 4). Branches, calls and returns overwrite it.' },
    { id: 'cu', label: 'Control unit', sub: 'fetch + decode', x: 2, y: 0, color: 'blue', info: 'Decodes the opcode and operands and drives the rest of the datapath. On modern x86 a complex instruction is split into simpler micro-ops, and a micro-op cache skips decoding for hot loops.' },
    { id: 'regs', label: 'Register file', sub: '16 GPRs on x86-64', x: 0, y: 2, color: 'green', info: 'The fastest storage, read in effectively 0 cycles. x86-64 has 16 general-purpose registers, ARM64 has 31, plus vector registers. Compilers work hard to keep hot values here.' },
    { id: 'alu', label: 'ALU / AGU', sub: 'execution ports', x: 2, y: 2, color: 'orange', info: 'Arithmetic and logic units do the maths; address generation units compute memory addresses such as [rbx + 8]. A modern core has several of each and runs them in parallel.' },
    { id: 'bus', label: 'Caches + bus', sub: 'addr · data · ctrl', x: 4, y: 1, shape: 'pill', color: 'gray', info: 'Historically one shared bus. Today it is L1i/L1d, L2, L3 and an on-die memory controller, but logically it is still one path that both instructions and data must use.' },
    { id: 'code', label: 'Instructions', sub: 'text segment', x: 6, y: 0, shape: 'db', color: 'teal', info: 'Machine code is just bytes in memory. The OS maps code pages read-only and executable, and data pages non-executable (NX bit), so injected data cannot be run as code.' },
    { id: 'data', label: 'Data', sub: 'heap + stack', x: 6, y: 2, shape: 'db', color: 'teal', info: 'Variables live in the same memory as code. A load or store competes with instruction fetch for the same path, which is the original von Neumann bottleneck.' },
  ],
  edges: [
    { from: 'pc', to: 'cu', both: true, label: 'PC / next PC' },
    { from: 'cu', to: 'bus', both: true, label: 'fetch' },
    { from: 'bus', to: 'code', both: true },
    { from: 'cu', to: 'regs', label: 'read operands' },
    { from: 'cu', to: 'alu', label: 'control' },
    { from: 'regs', to: 'alu', both: true, label: 'operands / result' },
    { from: 'alu', to: 'bus', both: true, label: 'load / store' },
    { from: 'bus', to: 'data', both: true },
  ],
  steps: [
    { caption: 'Fetch: the control unit sends the address in the program counter out to memory. The instruction usually comes from the L1 instruction cache in about 1 ns; a miss to DRAM costs about 100 ns, roughly 300 cycles.', flows: [{ from: 'pc', to: 'cu', label: '0x401000' }, { from: 'cu', to: 'bus', label: 'fetch' }, { from: 'bus', to: 'code', label: 'read' }] },
    { caption: 'The instruction bytes for add rax, [rbx] arrive at the control unit, and the PC is advanced past them so the next fetch can start right away.', flows: [{ from: 'code', to: 'bus', label: 'bytes' }, { from: 'bus', to: 'cu', label: 'add rax,[rbx]' }, { from: 'cu', to: 'pc', label: 'PC += 3' }] },
    { caption: 'Decode: the opcode says "add with a memory operand". On x86 this becomes two micro-ops, a load and an add, and the register operands rax and rbx are read.', flows: [{ from: 'cu', to: 'regs', label: 'read rbx, rax' }, { from: 'cu', to: 'alu', label: 'load + add' }] },
    { caption: 'Execute, memory part: the address unit uses rbx as the address and loads 8 bytes of data. This load uses the same memory path as instruction fetch.', flows: [{ from: 'regs', to: 'alu', label: 'rbx' }, { from: 'alu', to: 'bus', label: 'load [rbx]' }, { from: 'bus', to: 'data', label: 'read 8 B' }] },
    { caption: 'Execute and write back: the loaded value comes back, the ALU adds it to rax, and the result is written to the register file.', flows: [{ from: 'data', to: 'bus', label: 'value' }, { from: 'bus', to: 'alu', label: 'value' }, { from: 'alu', to: 'regs', label: 'rax = sum' }] },
    { caption: 'A branch or call simply writes a new value into the PC, and the loop starts again. A 3 GHz core runs this cycle billions of times a second, several instructions per cycle.', flows: [{ from: 'cu', to: 'pc', label: 'jump target' }] },
    { caption: 'The von Neumann bottleneck: the core can consume data far faster than DRAM can deliver it, and code and data share the path. Caches, prefetchers and out-of-order execution exist to hide this gap. Split L1i/L1d caches make modern cores a "modified Harvard" design.', active: ['bus', 'code', 'data', 'cu>bus', 'alu>bus', 'bus>data', 'bus>code'] },
    { caption: 'Go connection: a goroutine is little more than a saved PC, stack pointer and a few registers. The Go scheduler switches goroutines by loading those onto an OS thread, which is why a switch costs about 100 to 200 ns.', active: ['pc', 'regs'] },
  ],
});

// ===== Module 2: CPU Internals & Performance ===============================

registerDiagram({
  id: 'ca-pipeline-hazards',
  roadmap: 'computer-architecture', module: 2, topic: 'Pipelining & Hazards',
  kind: 'graph',
  title: '5-stage pipeline: overlap, a load-use stall and a branch flush',
  desc: 'Each instruction still needs 5 cycles, but a new one can enter every cycle. Watch the pipeline fill, then see the two hazards that break the rhythm: using a value right after loading it, and a mispredicted branch.',
  nodes: [
    { id: 'ic', label: 'L1 I-cache', sub: 'instruction bytes', x: 0, y: 0, shape: 'db', color: 'teal', info: 'Supplies instruction bytes to fetch. A miss here starves the whole pipeline (front-end bound in perf terms).' },
    { id: 'bp', label: 'Branch predictor', sub: 'guesses next PC', x: 1.5, y: 0, color: 'purple', info: 'Predicts the direction and target of branches at fetch time, long before EX knows the real outcome. Modern predictors are 95 to 99%+ accurate on regular patterns.' },
    { id: 'bub', label: 'bubble (nop)', sub: 'stall cycle', x: 3, y: 0, ghost: true, color: 'red', enter: 5, exit: 7, info: 'The interlock injects a do-nothing slot into EX and holds the earlier stages, because the next instruction cannot run without the loaded value.' },
    { id: 'if', label: 'IF', sub: 'fetch', x: 0, y: 1, color: 'blue', info: 'Fetch the instruction at the PC from the I-cache and advance the PC.' },
    { id: 'id', label: 'ID', sub: 'decode + read regs', x: 1.5, y: 1, color: 'blue', info: 'Decode the instruction and read its source registers. The hazard-detection logic lives here: it stalls an instruction whose input is not ready.' },
    { id: 'ex', label: 'EX', sub: 'ALU / address', x: 3, y: 1, color: 'orange', info: 'Do the arithmetic or compute the memory address. Branches are resolved here in the classic design.' },
    { id: 'mem', label: 'MEM', sub: 'load / store', x: 4.5, y: 1, color: 'orange', info: 'Access the data cache. A load result is only available at the end of this stage.' },
    { id: 'wb', label: 'WB', sub: 'write register', x: 6, y: 1, color: 'green', info: 'Write the result into the register file. After this the instruction is complete.' },
    { id: 'rf', label: 'Register file', sub: 'r1 … r31', x: 1.5, y: 2, color: 'green', info: 'Read in ID, written in WB. Without forwarding, a dependent instruction would have to wait until WB has written the value.' },
    { id: 'dc', label: 'L1 D-cache', sub: '~4 cyc; miss 100+', x: 4.5, y: 0, shape: 'db', color: 'teal', info: 'A hit returns data in about 4 cycles on real cores. A miss to DRAM turns a one-cycle bubble into hundreds of stall cycles unless out-of-order execution finds other work.' },
  ],
  edges: [
    { from: 'ic', to: 'if' },
    { from: 'bp', to: 'if', label: 'predicted PC' },
    { from: 'if', to: 'id' },
    { from: 'id', to: 'ex' },
    { from: 'ex', to: 'mem' },
    { from: 'mem', to: 'wb' },
    { from: 'id', to: 'rf', both: true },
    { from: 'mem', to: 'dc', both: true },
    { id: 'fwd', from: 'mem', to: 'ex', curve: 50, label: 'forward' },
    { from: 'wb', to: 'rf', curve: -40, label: 'write back' },
    { from: 'ex', to: 'bp', label: 'actual outcome' },
    { from: 'bub', to: 'ex', dashed: true },
  ],
  steps: [
    { caption: 'Cycle 1: the load i1 (ld r1,[r2]) is fetched. The classic RISC pipeline has 5 stages; modern x86 and ARM cores have 10 to 20+.', flows: [{ from: 'ic', to: 'if', label: 'i1: ld r1,[r2]' }] },
    { caption: 'Cycle 2: i1 moves to decode and reads r2, while i2 (add r3,r1,r4) is fetched behind it. Different instructions now use different stages at the same time.', flows: [{ from: 'if', to: 'id', label: 'i1' }, { from: 'ic', to: 'if', label: 'i2: add r3,r1,r4' }, { from: 'rf', to: 'id', label: 'r2' }] },
    { caption: 'Cycle 3: i1 computes its address in EX, i2 decodes, i3 is fetched. Once full, the pipeline completes one instruction per cycle: latency is still 5 cycles, but throughput is 5 times higher.', flows: [{ from: 'id', to: 'ex', label: 'i1' }, { from: 'if', to: 'id', label: 'i2' }, { from: 'ic', to: 'if', label: 'i3' }] },
    { caption: 'Load-use hazard, end of cycle 3: i2 in ID needs r1, but i1 in EX will only read r1 from the cache in MEM, next cycle. Hazard detection in ID spots this read-after-write dependency.', flows: [{ from: 'ex', to: 'id', label: 'r1 not ready', color: 'red' }] },
    { caption: 'Cycle 4: i1 reads the D-cache in MEM, while the interlock injects a bubble into EX and holds i2 in ID and i3 in IF. Even with forwarding, a load followed immediately by its use costs at least one bubble.', flows: [{ from: 'ex', to: 'mem', label: 'i1' }, { from: 'mem', to: 'dc', label: 'read [r2]' }, { from: 'bub', to: 'ex', label: 'nop' }], active: ['id', 'if'] },
    { caption: 'Cycle 5: forwarding sends r1 straight from the MEM output to the EX input, skipping the register file. Without the bypass, i2 would wait two more cycles until WB. If the load had missed L1, the bubble would be tens to hundreds of cycles.', flows: [{ from: 'mem', to: 'ex', label: 'r1 forwarded' }, { from: 'id', to: 'ex', label: 'i2 add' }, { from: 'mem', to: 'wb', label: 'i1' }] },
    { caption: 'Control hazard: fetch meets a branch whose outcome is only known in EX. Rather than wait, the predictor guesses and IF keeps fetching down the predicted path.', flows: [{ from: 'bp', to: 'if', label: 'guess: taken' }, { from: 'if', to: 'id', label: 'wrong-path i' }] },
    { caption: 'EX resolves the branch as not taken: a mispredict. Every younger instruction fetched down the wrong path is flushed. On deep modern pipelines that wastes about 15 to 20 cycles, so a coin-flip branch in a hot loop is very expensive.', flows: [{ from: 'ex', to: 'bp', label: 'not taken!', color: 'red' }, { from: 'id', to: 'if', label: 'flush', color: 'red' }] },
    { caption: 'Write back and the software lesson: a chain of dependent operations runs at the latency of each step, while independent ones fill the pipeline. Several accumulators in a reduction, or a slice instead of a linked list, can be several times faster with the same instruction count.', flows: [{ from: 'wb', to: 'rf', label: 'r3' }], active: ['fwd', 'ex', 'mem'] },
  ],
});

registerDiagram({
  id: 'ca-ooo-core',
  roadmap: 'computer-architecture', module: 2, topic: 'Superscalar, Out-of-Order & Speculative Execution',
  kind: 'graph',
  title: 'Inside an out-of-order core: rename, schedule, retire',
  desc: 'The front end fetches in program order along the predicted path, the back end executes whatever is ready, and the reorder buffer puts results back in order. Press Play to follow micro-ops through the core, including a mispredict and the Spectre side effect.',
  groups: [
    { id: 'front', label: 'In-order front end', x: 0, y: 0, w: 5, h: 1, color: 'blue' },
    { id: 'back', label: 'Out-of-order back end', x: 1, y: 2, w: 6, h: 3, color: 'orange' },
  ],
  nodes: [
    { id: 'fetch', label: 'Fetch + predict', sub: '16–32 B per cycle', x: 0, y: 0, color: 'blue', info: 'Fetches instruction bytes along the path the branch predictor chose. It never waits for a branch to resolve.' },
    { id: 'dec', label: 'Decode', sub: '4–8 micro-ops/cycle', x: 2, y: 0, color: 'blue', info: 'Turns x86 or ARM instructions into micro-ops. Hot loops are served from a micro-op cache to save decode power and bandwidth.' },
    { id: 'ren', label: 'Rename (RAT)', sub: 'arch → physical regs', x: 4, y: 0, color: 'purple', info: 'Maps the 16 (x86-64) or 31 (ARM64) architectural registers onto hundreds of physical registers. Two writes to rax become writes to different physical registers, removing false WAR and WAW dependencies.' },
    { id: 'bp', label: 'Branch predictor', sub: 'TAGE-like history', x: 0, y: 2, color: 'purple', info: 'Uses global branch history to predict direction and a branch target buffer to predict the address. Mispredicts cost about 15 to 20 cycles.' },
    { id: 'rs', label: 'Scheduler (RS)', sub: 'waits for operands', x: 4, y: 2, color: 'orange', info: 'Reservation stations hold micro-ops until their inputs are ready, then issue them to a free execution port. Ready means ready, not oldest: this is the out-of-order part.' },
    { id: 'rob', label: 'Reorder buffer', sub: '~200–600 entries', x: 6, y: 2, color: 'yellow', info: 'Every micro-op gets a slot in program order. Results are marked done as they finish, but only the oldest finished entries retire, so exceptions and interrupts stay precise.' },
    { id: 'alu', label: 'ALU ports', sub: 'add · cmp · branch', x: 2, y: 4, color: 'orange', info: 'Several integer ports work in parallel, so a core can execute 4 to 8 simple operations per cycle when the code has enough independent work.' },
    { id: 'lsu', label: 'Load / store', sub: '10+ misses in flight', x: 4, y: 4, color: 'orange', info: 'Load and store units plus line fill buffers that track outstanding cache misses. This is what makes memory-level parallelism possible.' },
    { id: 'vec', label: 'Vector / FP', sub: 'SSE · AVX · NEON', x: 6, y: 4, color: 'orange', info: 'SIMD and floating-point ports. One AVX2 instruction processes 8 int32 values at once.' },
    { id: 'mem', label: 'Caches / DRAM', sub: 'L1d → L2 → L3 → RAM', x: 4, y: 6, shape: 'db', color: 'teal', info: 'Loads that miss go down the hierarchy. Speculative loads fill cache lines too, and those lines stay even if the work is thrown away.' },
    { id: 'ret', label: 'Retire', sub: 'commit in order', x: 6, y: 0, shape: 'pill', color: 'green', info: 'Retirement makes results architecturally visible: registers and memory now reflect the instruction. Squashed micro-ops never reach this point.' },
  ],
  edges: [
    { from: 'fetch', to: 'dec' },
    { from: 'dec', to: 'ren' },
    { from: 'bp', to: 'fetch', label: 'next PC' },
    { from: 'ren', to: 'rs', label: 'micro-ops' },
    { from: 'ren', to: 'rob', label: 'ROB slot' },
    { from: 'rs', to: 'alu' },
    { from: 'rs', to: 'lsu' },
    { from: 'rs', to: 'vec' },
    { from: 'lsu', to: 'mem', both: true, label: 'misses in flight' },
    { from: 'alu', to: 'rob' },
    { from: 'lsu', to: 'rob' },
    { from: 'vec', to: 'rob' },
    { from: 'rob', to: 'ret', label: 'oldest first' },
    { from: 'alu', to: 'bp', dashed: true, label: 'mispredict: flush' },
  ],
  steps: [
    { caption: 'The predictor chooses the path and the front end fetches along it, many bytes per cycle. Fetch never stalls on a branch: it bets and keeps going.', flows: [{ from: 'bp', to: 'fetch', label: 'predict taken' }, { from: 'fetch', to: 'dec', label: 'bytes' }] },
    { caption: 'Decode produces micro-ops and rename gives every destination a fresh physical register. Two unrelated uses of rax no longer have to wait for each other.', flows: [{ from: 'dec', to: 'ren', label: 'micro-ops' }] },
    { caption: 'Each micro-op enters the scheduler and also takes a reorder-buffer slot in program order. The ROB is the record of the original order.', flows: [{ from: 'ren', to: 'rs', label: 'add, load, fma' }, { from: 'ren', to: 'rob', label: 'in order' }] },
    { caption: 'Out-of-order issue: any micro-op whose inputs are ready goes to a free port, even if an older one is still waiting for a cache miss. That is how a superscalar core reaches 3 to 5 instructions per cycle on good code.', flows: [{ from: 'rs', to: 'alu', label: 'add' }, { from: 'rs', to: 'lsu', label: 'load A, B' }, { from: 'rs', to: 'vec', label: 'fma' }] },
    { caption: 'Memory-level parallelism: independent loads can have 10 to 20+ misses outstanding at once. Iterating a slice issues independent loads; walking a linked list is pointer chasing, so misses are serialised. Same big-O, often 5 to 20 times slower.', flows: [{ from: 'lsu', to: 'mem', label: 'A, B, C, D' }] },
    { caption: 'Results come back in whatever order they finish and are marked done in the ROB. Nothing is architecturally visible yet.', flows: [{ from: 'alu', to: 'rob', label: 'done' }, { from: 'mem', to: 'lsu', label: 'data' }, { from: 'lsu', to: 'rob', label: 'done' }, { from: 'vec', to: 'rob', label: 'done' }] },
    { caption: 'The ROB retires the oldest finished micro-ops in program order. If one of them faulted, everything younger is discarded, so exceptions look precise to software.', flows: [{ from: 'rob', to: 'ret', label: 'commit' }] },
    { caption: 'Mispredict: the branch executes in an ALU and disagrees with the prediction. All younger micro-ops in the ROB and scheduler are squashed and fetch restarts at the right address, about 15 to 20 cycles lost.', flows: [{ from: 'alu', to: 'bp', label: 'flush', color: 'red' }], active: ['rob', 'rs'] },
    { caption: 'Spectre: squashed loads already pulled secret-dependent lines into the cache, and timing can reveal which. Mitigations such as KPTI and retpolines made syscalls and context switches noticeably more expensive, one more reason to batch syscalls.', flows: [{ from: 'lsu', to: 'mem', label: 'leaves a trace', color: 'red' }], active: ['mem'] },
  ],
});

// ===== Module 3: Memory Hierarchy & Caches =================================

registerDiagram({
  id: 'ca-memory-hierarchy',
  roadmap: 'computer-architecture', module: 3, topic: 'The Memory Hierarchy & Latency Numbers',
  kind: 'graph',
  title: 'A cache miss all the way down, and the line coming back',
  desc: 'Each level is bigger and slower than the one above and caches it. Follow one load that misses everywhere, then see why the very next load is almost free. Figures are typical for a ~3 GHz server core.',
  groups: [
    { id: 'core0', label: 'Core 0', x: 0, y: 0, w: 1, h: 3, color: 'blue' },
    { id: 'core1', label: 'Core 1', x: 2, y: 0, w: 1, h: 3, color: 'blue' },
  ],
  nodes: [
    { id: 'r0', label: 'Registers', sub: '0 cycles', x: 0, y: 0, color: 'green', info: '16 general-purpose registers plus vector registers per thread. Values the compiler keeps here cost nothing to read.' },
    { id: 'l1a', label: 'L1d 48 KiB', sub: '~4 cycles · 1 ns', x: 0, y: 1, color: 'green', info: 'Private per core, split into instruction and data caches. Delivers 100+ GB/s per core. Lines are 64 bytes.' },
    { id: 'l2a', label: 'L2 2 MiB', sub: '~14 cycles · 4 ns', x: 0, y: 2, color: 'yellow', info: 'Private per core on most server CPUs. Holds the working set that does not fit in L1.' },
    { id: 'r1', label: 'Registers', sub: '0 cycles', x: 2, y: 0, color: 'green', info: 'Core 1 has its own registers, L1 and L2.' },
    { id: 'l1b', label: 'L1d 48 KiB', sub: '~4 cycles · 1 ns', x: 2, y: 1, color: 'green', info: 'Private to core 1. Hardware coherence (MESI) keeps it consistent with core 0.' },
    { id: 'l2b', label: 'L2 2 MiB', sub: '~14 cycles · 4 ns', x: 2, y: 2, color: 'yellow', info: 'Private to core 1.' },
    { id: 'l3', label: 'L3 (LLC), shared', sub: '32–100+ MiB · ~15 ns', x: 0, y: 3, w: 3, color: 'orange', info: 'The last-level cache, shared by all cores on the socket (or on a chiplet). About 40 to 70 cycles. It is also where cores find lines another core has recently used.' },
    { id: 'dram', label: 'DRAM (local)', sub: '64 GiB+ · ~100 ns', x: 0, y: 4, w: 3, shape: 'db', color: 'red', info: 'About 300 cycles away, enough time for roughly 1000 instructions. A 12-channel DDR5 socket peaks around 450 to 600 GB/s, but it is shared by 100+ cores: a single core streaming alone gets roughly 10 to 30 GB/s.' },
    { id: 'rem', label: 'Remote DRAM', sub: 'other socket ~150 ns', x: 5, y: 4, shape: 'db', ghost: true, color: 'red', info: 'On a multi-socket (NUMA) server, memory attached to the other socket costs about 1.3 to 2 times the local latency, with lower bandwidth.' },
    { id: 'ssd', label: 'NVMe SSD', sub: 'TBs · 20–100 µs', x: 0, y: 6, w: 3, shape: 'db', color: 'purple', info: 'Not part of the hardware cache hierarchy: the OS moves data between SSD and DRAM through the page cache, page faults and explicit I/O. If L1 took 1 second, an SSD read would take about a day.' },
  ],
  edges: [
    { from: 'r0', to: 'l1a' },
    { from: 'l1a', to: 'l2a' },
    { from: 'l2a', to: 'l3' },
    { from: 'r1', to: 'l1b' },
    { from: 'l1b', to: 'l2b' },
    { from: 'l2b', to: 'l3' },
    { from: 'l3', to: 'dram' },
    { from: 'dram', to: 'rem', both: true, label: 'UPI / Infinity Fabric' },
    { from: 'dram', to: 'ssd', both: true, label: 'OS: page cache, faults' },
  ],
  steps: [
    { caption: 'Core 0 executes a load of x. The L1 data cache is checked first, in about 4 cycles, and misses.', flows: [{ from: 'r0', to: 'l1a', label: 'load x' }, { from: 'l1a', to: 'l2a', label: 'L1 miss' }] },
    { caption: 'L2 misses too (about 14 cycles spent), then the shared L3 (about 40 to 70 cycles). The request goes to the memory controller.', flows: [{ from: 'l2a', to: 'l3', label: 'L2 miss' }, { from: 'l3', to: 'dram', label: 'L3 miss' }] },
    { caption: 'DRAM returns a whole 64-byte cache line, not just the 8 bytes asked for, and it is installed at every level on the way up. Total about 100 ns, about 300 cycles: the core could have run about 1000 instructions.', flows: [{ from: 'dram', to: 'l3', label: '64 B line' }, { from: 'l3', to: 'l2a', label: 'line' }, { from: 'l2a', to: 'l1a', label: 'line' }] },
    { caption: 'Spatial locality: the next load of x+8 is in the same line, so it hits L1 in about 1 ns. Sequential access pays one miss per 64 bytes, and the prefetcher hides even that.', flows: [{ from: 'l1a', to: 'r0', label: 'x+8: hit, 1 ns' }] },
    { caption: 'Core 1 now reads x. Its private L1 and L2 miss, but the line is in the shared L3, so it costs about 15 ns instead of 100.', flows: [{ from: 'r1', to: 'l1b', label: 'load x' }, { from: 'l2b', to: 'l3', label: 'miss' }, { from: 'l3', to: 'l2b', label: 'L3 hit' }] },
    { caption: 'On a two-socket server, memory that lives on the other socket crosses the interconnect: about 130 to 200 ns. A process that allocates on one node and runs on the other pays this on every miss.', flows: [{ from: 'dram', to: 'rem', label: 'remote line' }], active: ['rem'] },
    { caption: 'Below DRAM, data moves only through the OS: a page-cache miss or major page fault reads from NVMe in about 20 to 100 µs. On the "L1 = 1 second" scale, that is about a day.', flows: [{ from: 'ssd', to: 'dram', label: '4 KiB page' }] },
    { caption: 'The backend lesson: keep the hot working set small and contiguous so it stays high in this pyramid. The same ladder repeats one level up: in-process cache (ns), Redis over the network (~0.5 ms), database on SSD (ms).', active: ['l1a', 'l2a', 'l3', 'dram'] },
  ],
});

registerDiagram({
  id: 'ca-cache-lookup',
  roadmap: 'computer-architecture', module: 3, topic: 'Cache Organisation: Associativity, Misses & Write Policies',
  kind: 'graph',
  title: 'Set-associative cache lookup: hit, miss, evict, fill',
  desc: 'A 48 KiB, 12-way cache with 64-byte lines has 64 sets. The address alone decides which set a line can live in. Follow a hit, then a miss that evicts a dirty line.',
  groups: [
    { id: 'addr', label: 'Address bits', x: 0, y: 0, w: 3, h: 1, color: 'purple' },
    { id: 'cache', label: 'L1d: 64 sets × 12 ways', x: 0, y: 2, w: 4, h: 1, color: 'blue' },
  ],
  nodes: [
    { id: 'tag', label: 'Tag', sub: 'upper bits', x: 0, y: 0, color: 'purple', info: 'Identifies which memory line is stored in a way. Stored next to each line along with valid and dirty bits.' },
    { id: 'idx', label: 'Index', sub: '6 bits → set 0–63', x: 1, y: 0, color: 'purple', info: '48 KiB / 64 B = 768 lines; 768 / 12 ways = 64 sets, so 6 index bits. Bits 6 to 11 of the address.' },
    { id: 'off', label: 'Offset', sub: '6 bits → byte 0–63', x: 2, y: 0, color: 'purple', info: 'Selects the byte within the 64-byte line. Bits 0 to 5.' },
    { id: 'set', label: 'Set 17', sub: '12 ways: tag + data', x: 1, y: 2, color: 'blue', info: 'The only place this address can be cached. All 12 tags are compared in parallel in the same cycle.' },
    { id: 'cmp', label: 'Tag match?', x: 3, y: 2, shape: 'diamond', color: 'yellow', info: 'A hit needs a matching tag and the valid bit set. With a virtually indexed, physically tagged L1, the TLB lookup runs in parallel with set selection.' },
    { id: 'hit', label: 'Hit: ~4 cycles', sub: 'return bytes', x: 5, y: 2, shape: 'pill', color: 'green', info: 'The offset picks the bytes out of the matched line. Writes on a hit just update the line and set its dirty bit (write-back).' },
    { id: 'vic', label: 'Pick a victim', sub: 'pseudo-LRU in set', x: 3, y: 4, color: 'orange', info: 'All 12 ways are full, so one must go. Hardware uses cheap approximations of LRU. Only lines in this set compete, which is why conflict misses exist.' },
    { id: 'l2', label: 'L2 cache', sub: '~14 cycles', x: 3, y: 6, shape: 'db', color: 'teal', info: 'The next level down. A dirty victim is written back here; the new line is read from here (or from further down).' },
  ],
  edges: [
    { from: 'idx', to: 'set', label: 'select set' },
    { from: 'tag', to: 'cmp', label: 'compare tag', curve: 30 },
    { from: 'set', to: 'cmp', label: '12 tags at once' },
    { from: 'cmp', to: 'hit', label: 'hit' },
    { from: 'off', to: 'hit', label: 'pick bytes' },
    { from: 'cmp', to: 'vic', label: 'miss' },
    { from: 'vic', to: 'l2', label: 'write back if dirty' },
    { from: 'l2', to: 'set', label: 'fill 64 B line' },
  ],
  steps: [
    { caption: 'The address is split into tag, index and offset. With 64-byte lines and 64 sets, the low 6 bits pick the byte and the next 6 bits pick the set; everything above is the tag.', active: ['tag', 'idx', 'off'] },
    { caption: 'The index selects set 17. In a 12-way cache this line may live in any of the 12 ways of set 17, and nowhere else.', flows: [{ from: 'idx', to: 'set', label: 'set 17' }] },
    { caption: 'All 12 stored tags in the set are compared with the address tag in parallel. Comparing in parallel is why associativity is expensive in power and area, and why L1 stays small.', flows: [{ from: 'tag', to: 'cmp', label: 'tag' }, { from: 'set', to: 'cmp', label: '12 tags' }] },
    { caption: 'Hit: the matching way supplies the line and the offset selects the bytes, in about 4 to 5 cycles. On a write hit, the line is updated and marked dirty; nothing goes to L2 yet (write-back).', flows: [{ from: 'cmp', to: 'hit', label: 'way 5' }, { from: 'off', to: 'hit', label: 'bytes 8–15' }] },
    { caption: 'Miss: no tag matched. It is compulsory if the line was never loaded, capacity if the working set is bigger than the cache, conflict if too many hot lines map to this one set, or coherence if another core invalidated it.', flows: [{ from: 'cmp', to: 'vic', label: 'miss', color: 'red' }] },
    { caption: 'The set is full, so pseudo-LRU picks a victim. If its dirty bit is set, it is written back to L2 first; a clean victim is simply dropped.', flows: [{ from: 'vic', to: 'l2', label: 'dirty line' }] },
    { caption: 'The new 64-byte line is fetched and installed in the freed way. For a store miss, write-allocate fetches the line first and gains ownership: the read for ownership (RFO).', flows: [{ from: 'l2', to: 'set', label: 'new line' }] },
    { caption: 'Conflict trap: addresses 4096 bytes apart have the same index bits, so they all land in one set. Striding by 4 KiB, like walking a column of a power-of-two matrix, thrashes 12 slots while the other 63 sets sit idle. Padding rows fixes it.', active: ['idx', 'set'] },
  ],
});

registerDiagram({
  id: 'ca-mesi-false-sharing',
  roadmap: 'computer-architecture', module: 3, topic: 'Cache Coherence (MESI) & False Sharing',
  kind: 'sequence',
  title: 'MESI messages behind false sharing',
  desc: 'Two goroutines on two cores each increment their own counter, a and b, but both counters sit in the same 64-byte line L. The program shares nothing; the hardware shares the line.',
  actors: [
    { id: 'c0', label: 'Core 0 + L1', sub: 'goroutine: a++', icon: '⚙️', color: 'blue', info: 'Private L1 and L2. To write a line it must hold it in Modified or Exclusive state.' },
    { id: 'llc', label: 'L3 + snoop filter', sub: 'tracks who has L', color: 'purple', info: 'The shared L3 and its directory (snoop filter) know which cores may hold each line, so invalidations go only where needed. Across sockets the same messages travel over the interconnect, which is slower.' },
    { id: 'c1', label: 'Core 1 + L1', sub: 'goroutine: b++', icon: '⚙️', color: 'blue', info: 'Writes counter b, which happens to be the next 8 bytes after a in the same struct or slice.' },
    { id: 'mem', label: 'DRAM', sub: 'home of line L', color: 'teal', info: 'Only involved on the first miss and on write-back of dirty lines.' },
  ],
  steps: [
    { section: 'Both cores read the line' },
    { from: 'c0', to: 'llc', label: 'read line L', caption: 'Core 0 reads a. Its L1 misses, so it asks the L3. Coherence works on whole 64-byte lines, never on single variables.' },
    { from: 'llc', to: 'mem', label: 'fetch 64 B', caption: 'No cache has line L yet, so it comes from DRAM, about 100 ns.' },
    { from: 'mem', to: 'llc', label: 'line L', reply: true, caption: 'DRAM returns the line. It now holds both a and b.' },
    { from: 'llc', to: 'c0', label: 'data, state E', reply: true, caption: 'Core 0 is the only holder, so it gets the line in Exclusive state. E can be written silently: it becomes M with no bus traffic.' },
    { from: 'c1', to: 'llc', label: 'read line L', caption: 'Core 1 reads b, which lives in the same line.' },
    { from: 'llc', to: 'c1', label: 'data, S (core 0: E→S)', reply: true, caption: 'Now two cores hold the line, so both copies are Shared. A Shared line is clean and read-only: writing requires invalidating everyone else first.' },
    { section: 'False sharing: the line ping-pongs' },
    { from: 'c0', to: 'c0', label: 'a++ needs M', caption: 'Core 0 wants to increment a. The line is only Shared, so it cannot write yet.' },
    { from: 'c0', to: 'llc', label: 'RFO line L', caption: 'Core 0 sends a read for ownership: "give me L exclusively and invalidate all other copies".' },
    { from: 'llc', to: 'c1', label: 'invalidate L', caption: 'The directory knows core 1 has a copy and sends it an invalidation, even though core 1 never touches a.' },
    { from: 'c1', to: 'llc', label: 'ack, S → I', reply: true, caption: 'Core 1 drops its copy to Invalid and acknowledges.' },
    { from: 'llc', to: 'c0', label: 'ownership: M', reply: true, caption: 'Core 0 holds L in Modified state and finally writes a. Every core-to-core hand-off like this costs tens of nanoseconds, more across sockets.' },
    { from: 'c1', to: 'llc', label: 'RFO (b++)', caption: 'Core 1 now increments b. Its copy is Invalid, so it needs the line back with ownership.' },
    { from: 'llc', to: 'c0', label: 'snoop: give up L', caption: 'Core 0 holds the only, dirty copy, so it must surrender it.' },
    { from: 'c0', to: 'llc', label: 'dirty line, M → I', reply: true, caption: 'Core 0 supplies the modified data and invalidates its copy. Its next a++ will miss again.' },
    { from: 'llc', to: 'c1', label: 'line, state M', reply: true, caption: 'Core 1 writes b. At millions of increments per second the line bounces constantly and both loops run many times slower than on one core.' },
    { section: 'The fix' },
    { from: 'c0', to: 'c0', label: 'pad to 128 B', caption: 'Give each hot per-core value its own line: pad to 128 bytes (Intel prefetches lines in pairs), or keep counters local and merge at the end. Go has cpu.CacheLinePad; perf c2c finds the culprits.' },
  ],
});

// ===== Module 4: Virtual Memory ============================================

registerDiagram({
  id: 'ca-tlb-page-walk',
  roadmap: 'computer-architecture', module: 4, topic: 'Multi-Level Page Tables & the TLB',
  kind: 'graph',
  title: 'Virtual to physical: TLB hit, 4-level page walk, page fault',
  desc: 'Every load and store uses a virtual address. The TLB usually translates it for free; on a miss the hardware walks a 4-level tree, and if the page is not present the kernel takes over.',
  groups: [
    { id: 'walk', label: 'HW page walk', x: 0, y: 2, w: 6, h: 1, color: 'blue' },
    { id: 'kern', label: 'Kernel (page-fault handler)', x: 0, y: 4, w: 6, h: 1, color: 'red' },
  ],
  nodes: [
    { id: 'cpu', label: 'CPU: load [VA]', sub: 'VPN + 12-bit offset', x: 0, y: 0, color: 'gray', info: 'With 4 KiB pages, the low 12 bits are the offset within the page and pass through unchanged. The upper 36 bits (of a 48-bit address) are the virtual page number that needs translating.' },
    { id: 'tlb', label: 'TLB', sub: '64 + ~2K entries', x: 2, y: 0, color: 'purple', info: 'A small cache of recent translations: a 64 to 96 entry L1 (Intel keeps 2 MiB pages in a separate ~32-entry array, about 64 MiB) backed by a shared L2 STLB of 1.5K to 4K entries. With 4 KiB pages the STLB reaches only about 6 to 16 MiB; with 2 MiB pages, several GiB. Entries are tagged with a PCID/ASID so a process switch need not flush them.' },
    { id: 'l1', label: 'L1d cache', sub: 'physically tagged', x: 4, y: 0, shape: 'db', color: 'teal', info: 'The physical address (frame number + offset) is used to check the cache. L1 lookup overlaps with the TLB lookup, so a TLB hit adds about 0 to 1 cycle.' },
    { id: 'pml4', label: 'PML4', sub: 'index VA[47:39]', x: 0, y: 2, color: 'blue', info: 'Top level. CR3 holds its physical address. Each table is one 4 KiB page of 512 eight-byte entries, so each level consumes 9 bits.' },
    { id: 'pdpt', label: 'PDPT', sub: 'index VA[38:30]', x: 1.5, y: 2, color: 'blue', info: 'Level 3. An entry here can also map a 1 GiB huge page directly.' },
    { id: 'pd', label: 'PD', sub: 'index VA[29:21]', x: 3, y: 2, color: 'blue', info: 'Level 2. An entry here can map a 2 MiB huge page, ending the walk one level early.' },
    { id: 'pt', label: 'PT → PTE', sub: 'index VA[20:12]', x: 4.5, y: 2, color: 'blue', info: 'The last level holds the page-table entry: physical frame number plus present, writable, user, no-execute, accessed and dirty bits.' },
    { id: 'pf', label: 'Page fault (#PF)', sub: 'CR2 = faulting VA', x: 4.5, y: 4, color: 'red', info: 'The CPU stops the instruction, saves the faulting address in CR2 and jumps to the kernel handler.' },
    { id: 'vma', label: 'Find VMA', sub: 'valid? permitted?', x: 2.25, y: 4, color: 'orange', info: 'The kernel looks up the virtual memory area that contains the address: heap arena, mmapped file, stack. It decides whether this is a legal access that just needs a page.' },
    { id: 'segv', label: 'SIGSEGV', sub: 'no VMA / bad perms', x: 0, y: 4, shape: 'pill', color: 'red', info: 'No mapping or a permission violation. Go catches the signal and turns a fault near address 0 into a nil-pointer panic.' },
    { id: 'disk', label: 'Disk / swap', sub: 'major fault', x: 2.25, y: 6, shape: 'db', color: 'purple', info: 'File-backed page not in the page cache, or an anonymous page that was swapped out: 10 to 100 µs on NVMe, about 10 ms on HDD.' },
  ],
  edges: [
    { from: 'cpu', to: 'tlb', label: 'VA' },
    { from: 'tlb', to: 'l1', label: 'PA' },
    { from: 'tlb', to: 'pml4', label: 'TLB miss' },
    { from: 'pml4', to: 'pdpt' },
    { from: 'pdpt', to: 'pd' },
    { from: 'pd', to: 'pt' },
    { from: 'pt', to: 'tlb', label: 'fill TLB' },
    { from: 'pt', to: 'pf', label: 'present = 0' },
    { from: 'pf', to: 'vma' },
    { from: 'vma', to: 'segv', label: 'invalid' },
    { from: 'vma', to: 'disk', both: true, label: 'read page' },
    { from: 'vma', to: 'pt', label: 'set PTE, retry' },
  ],
  steps: [
    { caption: 'A load uses a virtual address. With 4 KiB pages the low 12 bits are the page offset and stay as they are; the 36-bit virtual page number must become a physical frame number.', flows: [{ from: 'cpu', to: 'tlb', label: 'VA' }] },
    { caption: 'TLB hit: the translation was cached, so the physical address is ready almost immediately and the L1 lookup proceeds. This is the common case, well over 99% of accesses for cache-friendly code.', flows: [{ from: 'tlb', to: 'l1', label: 'frame | offset' }] },
    { caption: 'TLB miss: the hardware page walker starts at the table whose physical address is in CR3. A flat table for 48-bit addresses would need 512 GiB per process; the radix tree only allocates populated parts.', flows: [{ from: 'tlb', to: 'pml4', label: 'walk', color: 'red' }] },
    { caption: 'Each level uses 9 bits of the address to index a 512-entry table and yields the next table\'s address. The reads are dependent, so they cannot overlap.', flows: [{ from: 'pml4', to: 'pdpt', label: 'next table' }, { from: 'pdpt', to: 'pd', label: 'next table' }] },
    { caption: 'The fourth read returns the PTE. Its frame number fills the TLB and the access completes. A walk costs tens of cycles if the entries are cached, hundreds if not; big random-access heaps can lose 10 to 30% of cycles here. Huge pages end the walk at PD.', flows: [{ from: 'pd', to: 'pt', label: 'PTE' }, { from: 'pt', to: 'tlb', label: 'fill' }] },
    { caption: 'If the PTE says not present (or the access breaks its permission bits), the CPU raises a page fault and records the address in CR2.', flows: [{ from: 'pt', to: 'pf', label: 'P = 0', color: 'red' }] },
    { caption: 'The kernel finds the VMA. A first touch of anonymous memory is a minor fault: grab a zeroed frame, about 0.1 to 1 µs. So are pages already in the page cache and copy-on-write copies.', flows: [{ from: 'pf', to: 'vma', label: 'fault addr' }] },
    { caption: 'A major fault must read the page from a file or swap first, 10 to 100 µs on NVMe. Your code just sees a slow memory access, and the thread blocks.', flows: [{ from: 'vma', to: 'disk', label: 'read 4 KiB' }, { from: 'disk', to: 'vma', label: 'page' }] },
    { caption: 'The kernel writes the PTE and returns. The faulting instruction re-executes, this time the walk succeeds, and the program never knows it happened.', flows: [{ from: 'vma', to: 'pt', label: 'PTE present' }] },
    { caption: 'No VMA, or writing a read-only page: the kernel sends SIGSEGV. The Go runtime handles the signal and turns a fault near address 0 into a nil-pointer panic.', flows: [{ from: 'vma', to: 'segv', label: 'SIGSEGV', color: 'red' }] },
  ],
});

registerDiagram({
  id: 'ca-cow-fork',
  roadmap: 'computer-architecture', module: 4, topic: 'Copy-on-Write, fork() & mmap',
  kind: 'graph',
  title: 'fork() with copy-on-write: share first, copy on write',
  desc: 'fork() copies the page tables, not the memory. Parent and child share every frame read-only until one of them writes. This is how Redis BGSAVE snapshots a large dataset almost instantly.',
  nodes: [
    { id: 'ppt', label: 'Parent page table', sub: 'Redis main process', x: 1, y: 0, w: 3, color: 'blue', info: 'Keeps serving writes while the child saves the snapshot.' },
    { id: 'kern', label: 'Kernel: #PF', sub: 'alloc + copy 4 KiB', x: 6, y: 0, color: 'red', info: 'Handles the write fault on a COW page: if the frame is still shared it allocates a new one, copies the contents and remaps the writer. If the writer is the last user, it just makes the PTE writable again.' },
    { id: 'fa', label: 'Frame A', sub: 'code (r-x)', x: 0, y: 2, shape: 'db', color: 'teal', info: 'Code is read-only anyway, so it stays shared for the life of both processes.' },
    { id: 'fb', label: 'Frame B', sub: 'heap page', x: 2, y: 2, shape: 'db', color: 'teal', info: 'A writable heap page, temporarily mapped read-only in both processes with a reference count of 2.' },
    { id: 'fc', label: 'Frame C', sub: 'heap page', x: 4, y: 2, shape: 'db', color: 'teal', info: 'Never written after the fork, so it is never copied.' },
    { id: 'fb2', label: "Frame B'", sub: 'private copy', x: 6, y: 2, shape: 'db', color: 'orange', enter: 5, info: 'The parent\'s new private copy of B. Memory use grows by one page for every page written while the child is alive.' },
    { id: 'cpt', label: 'Child page table', sub: 'BGSAVE: writes RDB', x: 1, y: 4, w: 3, color: 'purple', enter: 2, info: 'The child sees a frozen snapshot of memory at the moment of fork and streams it to disk.' },
  ],
  edges: [
    { from: 'ppt', to: 'fa' },
    { from: 'ppt', to: 'fb' },
    { from: 'ppt', to: 'fc' },
    { from: 'cpt', to: 'fa' },
    { from: 'cpt', to: 'fb' },
    { from: 'cpt', to: 'fc' },
    { from: 'ppt', to: 'kern', label: 'write → fault' },
    { from: 'kern', to: 'fb2', label: 'new frame' },
    { from: 'fb', to: 'fb2', curve: 90, dashed: true, label: 'copy 4 KiB' },
    { from: 'ppt', to: 'fb2' },
  ],
  steps: [
    { caption: 'Before the fork, the parent\'s page table maps frames A, B and C with their normal permissions.', active: ['ppt', 'fa', 'fb', 'fc', 'ppt>fa', 'ppt>fb', 'ppt>fc'] },
    { caption: 'fork(): the kernel copies the page tables, not the pages, and marks every private writable page read-only in both processes. Frame reference counts become 2. For a 20 GiB process the page tables alone are about 40 MiB, so the fork itself can pause Redis for tens of milliseconds.', active: ['cpt', 'ppt', 'cpt>fa', 'cpt>fb', 'cpt>fc'] },
    { caption: 'Reads cost nothing: both processes read the same physical frames. The child can walk the whole dataset without a single copy.', flows: [{ from: 'cpt', to: 'fb', label: 'read' }, { from: 'cpt', to: 'fc', label: 'read' }, { from: 'ppt', to: 'fa', label: 'exec' }] },
    { caption: 'The parent handles SET and writes to frame B. The PTE is read-only, so the CPU raises a page fault, and the kernel sees it is a COW page rather than a real violation.', flows: [{ from: 'ppt', to: 'fb', label: 'write', color: 'red' }, { from: 'ppt', to: 'kern', label: '#PF' }] },
    { caption: 'Minor fault: the kernel allocates a new frame B\' and copies the 4 KiB, about a microsecond.', flows: [{ from: 'kern', to: 'fb2', label: 'alloc' }, { from: 'fb', to: 'fb2', label: 'copy' }] },
    { caption: 'The parent\'s PTE now points to B\' with write permission, and the write is retried and succeeds. The child keeps the original B, unchanged, so its snapshot stays consistent.', flows: [{ from: 'ppt', to: 'fb2', label: 'write OK' }], active: ['cpt', 'fb', 'cpt>fb'] },
    { caption: 'The catch: under a heavy write load every touched page is copied, so memory can approach 2 times the dataset. With transparent huge pages, each fault copies 2 MiB instead of 4 KiB, which is why Redis asks you to disable THP.', active: ['fb2', 'kern', 'fb'] },
    { caption: 'fork + exec replaces the child image at once, so copying anything is wasted. Go\'s os/exec uses clone(CLONE_VM|CLONE_VFORK) to skip even the page-table copy. A Go program cannot safely fork without exec: only the calling thread survives in the child.', active: ['cpt'] },
  ],
});

registerDiagram({
  id: 'ca-oom-flow',
  roadmap: 'computer-architecture', module: 4, topic: 'Overcommit, the OOM Killer, RSS vs VSZ & cgroup Memory Limits',
  kind: 'graph',
  title: 'From malloc to OOMKilled: how a container hits its memory limit',
  desc: 'Allocations only reserve address space; memory is charged to the container\'s cgroup when pages are first touched. Follow one page fault through memory.high throttling, memory.max reclaim and, when that fails, the cgroup OOM killer and exit code 137.',
  groups: [
    { id: 'cg', label: 'Kernel: memory cgroup charge path', x: 0, y: 2, w: 7, h: 3, color: 'blue' },
    { id: 'oomg', label: 'Out of memory', x: 2, y: 6, w: 5, h: 1, color: 'red' },
  ],
  nodes: [
    { id: 'alloc', label: 'Heap grows', sub: 'mmap: address space', x: 0, y: 0, color: 'gray', info: 'Go\'s heap, malloc or a JVM reserve virtual address space with mmap. Linux overcommits, so this almost never fails: VSZ jumps, RSS and memory.current do not change yet.' },
    { id: 'fault', label: 'First touch', sub: 'page fault', x: 2, y: 0, color: 'orange', info: 'The first write to each 4 KiB page faults. The kernel must find a physical frame, zero it and map it. This is where memory becomes real.' },
    { id: 'charge', label: 'Charge cgroup', sub: 'memory.current += 4K', x: 4, y: 0, color: 'purple', info: 'Every page is charged to one memory cgroup: anonymous memory, page cache, tmpfs/shmem and kernel objects such as socket buffers all count toward memory.current.' },
    { id: 'dmax', label: 'Over max?', sub: 'memory.max', x: 4, y: 2, w: 1.5, shape: 'diamond', color: 'red', info: 'memory.max is the hard limit (Kubernetes limits.memory). A charge that would exceed it is not allowed to proceed until the cgroup frees memory.' },
    { id: 'dhigh', label: 'Over high?', sub: 'memory.high', x: 1.75, y: 2, w: 1.5, shape: 'diamond', color: 'yellow', info: 'memory.high is a soft limit. Kubernetes sets it only with the MemoryQoS feature; systemd and other managers use it to slow a cgroup down before it reaches the hard limit.' },
    { id: 'ok', label: 'Page mapped', sub: 'RSS grows', x: 0, y: 4, color: 'green', info: 'The PTE is installed and the instruction retries. RSS and memory.current have both grown by one page.' },
    { id: 'thr', label: 'Throttled', sub: 'reclaim, then sleep', x: 2, y: 4, color: 'yellow', info: 'Over memory.high, the task is made to reclaim memory and is put to sleep briefly on its way back to user mode. It gets slower instead of dying, and memory PSI rises.' },
    { id: 'recl', label: 'Reclaim in cgroup', sub: 'cache, dirty, swap', x: 6, y: 2, color: 'orange', info: 'Clean page cache is dropped, dirty pages are written back, and anonymous pages go to swap if the cgroup may swap. Anonymous memory without swap and tmpfs cannot be reclaimed.' },
    { id: 'dfail', label: 'Still over?', sub: 'after retries', x: 5.75, y: 4, w: 1.25, shape: 'diamond', color: 'red', info: 'The kernel retries reclaim several times. If the charge still does not fit, the cgroup is out of memory.' },
    { id: 'oom', label: 'cgroup OOM killer', sub: 'oom_score + adj', x: 6, y: 6, color: 'red', info: 'Picks the process with the highest badness: mostly its memory use, adjusted by oom_score_adj. Kubernetes sets the adj by QoS class: Guaranteed -997, BestEffort 1000, Burstable in between based on its request.' },
    { id: 'kill', label: 'SIGKILL', sub: 'whole cgroup dies', x: 4, y: 6, color: 'red', info: 'SIGKILL cannot be caught: no deferred functions, no graceful shutdown, in-flight requests fail. With memory.oom.group = 1 (set by the kubelet on cgroup v2) every process in the container dies together. memory.events oom_kill is incremented.' },
    { id: 'k8s', label: 'OOMKilled', sub: 'exit code 137', x: 2, y: 6, color: 'gray', info: 'The runtime reports exit code 137 (128 + 9) and reason OOMKilled; the kubelet restarts the container with backoff. Node-level pressure is different: the kubelet evicts pods before the kernel\'s global OOM killer runs.' },
  ],
  edges: [
    { from: 'alloc', to: 'fault', label: 'write' },
    { from: 'fault', to: 'charge' },
    { from: 'charge', to: 'dmax' },
    { from: 'dmax', to: 'dhigh', label: 'no' },
    { from: 'dhigh', to: 'ok', label: 'no' },
    { from: 'dhigh', to: 'thr', label: 'yes' },
    { from: 'thr', to: 'ok' },
    { from: 'dmax', to: 'recl', label: 'yes' },
    { from: 'recl', to: 'dfail' },
    { from: 'dfail', to: 'oom', label: 'yes' },
    { from: 'oom', to: 'kill' },
    { from: 'kill', to: 'k8s' },
  ],
  steps: [
    { caption: 'The heap grows by reserving address space with mmap. Linux overcommits, so this succeeds even beyond RAM: VSZ jumps, but nothing is charged yet. That is why malloc almost never fails on Linux.', flows: [{ from: 'alloc', to: 'fault', label: 'first write' }] },
    { caption: 'The first write to a page faults. The kernel allocates and zeroes a frame and charges it to the container\'s memory cgroup, together with any page cache, tmpfs and socket buffers the container uses.', flows: [{ from: 'fault', to: 'charge', label: 'charge 4 KiB' }] },
    { caption: 'Below both limits, the page is mapped and the instruction retries. This is the normal path: RSS and memory.current grow one page at a time as the heap is touched.', flows: [{ from: 'charge', to: 'dmax', label: 'check' }, { from: 'dmax', to: 'dhigh', label: 'under max' }, { from: 'dhigh', to: 'ok', label: 'under high' }] },
    { caption: 'Above memory.high (if set), the task must reclaim and is briefly put to sleep before returning to user mode. The service slows down and memory PSI climbs, an early warning before the hard limit.', flows: [{ from: 'dhigh', to: 'thr', label: 'over high' }, { from: 'thr', to: 'ok', label: 'slowed' }] },
    { caption: 'At memory.max the charge cannot proceed. The kernel reclaims inside this cgroup only: drops clean page cache, writes back dirty pages, swaps anonymous pages if allowed. Page cache alone almost never causes an OOM kill.', flows: [{ from: 'dmax', to: 'recl', label: 'over max', color: 'red' }] },
    { caption: 'If reclaim cannot free enough after several attempts, typically because the memory is anonymous heap with no swap, the cgroup is out of memory.', flows: [{ from: 'recl', to: 'dfail', label: 'not enough' }, { from: 'dfail', to: 'oom', label: 'OOM', color: 'red' }] },
    { caption: 'The cgroup OOM killer picks a victim by oom_score (mostly memory use) plus oom_score_adj and sends SIGKILL. No defer, no shutdown hooks; with memory.oom.group every process in the container dies at once.', flows: [{ from: 'oom', to: 'kill', label: 'SIGKILL', color: 'red' }] },
    { caption: 'Kubernetes reports reason OOMKilled, exit code 137, and restarts the container. For Go, the usual root cause is a heap goal of 2x the live heap: set GOMEMLIMIT to about 90% of the limit and bound caches and queues.', flows: [{ from: 'kill', to: 'k8s', label: 'exit 137' }] },
  ],
});

// ===== Module 5: Processes, Threads & Scheduling ===========================

registerDiagram({
  id: 'ca-process-states',
  roadmap: 'computer-architecture', module: 5, topic: 'Processes vs Threads: Resources, PCB & Process States',
  kind: 'graph',
  title: 'Task state machine, with the Linux ps codes',
  desc: 'Every process or thread (a Linux task_struct) moves between these states. Most of a server thread\'s life is spent waiting, not running. Letters are what ps and top show.',
  nodes: [
    { id: 'new', label: 'New', sub: 'fork / clone', x: 0, y: 1, shape: 'pill', color: 'gray', info: 'clone() creates a task_struct: PID/TID, saved registers, scheduling data, pointers to the memory map, open-file table and credentials. A thread is a task that shares its mm and file table with others.' },
    { id: 'ready', label: 'Ready', sub: 'R: on run queue', x: 2, y: 1, color: 'blue', info: 'Runnable and waiting for a CPU on a per-CPU run queue. ps shows R for both ready and running. More ready tasks than cores means queueing delay.' },
    { id: 'run', label: 'Running', sub: 'R: on a CPU', x: 4, y: 1, color: 'green', info: 'Executing on a core, in user or kernel mode, until it blocks, exits or is preempted.' },
    { id: 'zomb', label: 'Zombie', sub: 'Z: exit code kept', x: 6, y: 1, color: 'red', info: 'The task has exited and its memory is freed, but the entry stays until the parent calls wait() to collect the exit status. Many zombies mean a parent that never reaps.' },
    { id: 'wait', label: 'Waiting', sub: 'S or D: blocked', x: 2, y: 3, color: 'orange', info: 'S is interruptible sleep (socket read, futex, sleep). D is uninterruptible, usually disk or NFS I/O: signals, even SIGKILL, wait until it finishes, and D tasks count toward the load average.' },
    { id: 'stop', label: 'Stopped', sub: 'T: SIGSTOP / ptrace', x: 6, y: 3, color: 'purple', info: 'Suspended by SIGSTOP or SIGTSTP (Ctrl-Z), or by a debugger. SIGCONT makes it runnable again.' },
  ],
  edges: [
    { from: 'new', to: 'ready', label: 'admitted' },
    { id: 'sched', from: 'ready', to: 'run', curve: -30, label: 'scheduled' },
    { id: 'preempt', from: 'run', to: 'ready', curve: -30, label: 'preempted' },
    { from: 'run', to: 'wait', label: 'blocks: I/O, lock' },
    { from: 'wait', to: 'ready', label: 'wakeup' },
    { from: 'run', to: 'zomb', label: 'exit()' },
    { from: 'run', to: 'stop', label: 'SIGSTOP' },
    { from: 'stop', to: 'ready', label: 'SIGCONT' },
  ],
  steps: [
    { caption: 'fork() or clone() creates the task and its PCB (task_struct). With copy-on-write, a new process costs about 100 µs including exec; a new thread about 10 to 20 µs. It starts out ready, not running.', flows: [{ from: 'new', to: 'ready', label: 'admitted' }] },
    { caption: 'The scheduler picks it from the run queue (EEVDF since Linux 6.6, CFS before that) and context-switches it onto a core.', flows: [{ from: 'ready', to: 'run', label: 'dispatch' }], active: ['sched'] },
    { caption: 'Its time slice runs out, or a higher-priority task wakes up: an involuntary context switch puts it back on the run queue. Too many of these shows up as high nivcsw and CPU throttling.', flows: [{ from: 'run', to: 'ready', label: 'preempt' }], active: ['preempt'] },
    { caption: 'It calls read() on a socket with no data, or waits on a futex: a voluntary switch. It leaves the CPU entirely and uses no CPU while it sleeps in S state.', flows: [{ from: 'run', to: 'wait', label: 'read() blocks' }] },
    { caption: 'Data arrives, an interrupt handler wakes the task, and it goes back to the run queue. It does not jump straight to running: under load, this queueing is part of your tail latency.', flows: [{ from: 'wait', to: 'ready', label: 'data ready' }] },
    { caption: 'D state is the special case: uninterruptible sleep in the kernel, usually storage I/O. kill -9 has no effect until the I/O completes, and D tasks raise the load average even with idle CPUs.', active: ['wait'] },
    { caption: 'SIGSTOP (or a debugger) freezes the task in T state; SIGCONT makes it ready again.', flows: [{ from: 'run', to: 'stop', label: 'SIGSTOP' }, { from: 'stop', to: 'ready', label: 'SIGCONT' }] },
    { caption: 'On exit the memory is freed but the task stays a zombie until its parent calls wait(). In a container your app is often PID 1: it must reap orphans and handle SIGTERM itself, or use a tiny init such as tini.', flows: [{ from: 'run', to: 'zomb', label: 'exit(0)' }] },
  ],
});

registerDiagram({
  id: 'ca-syscall-path',
  roadmap: 'computer-architecture', module: 5, topic: 'User Mode vs Kernel Mode & System Calls',
  kind: 'graph',
  title: 'A Go file read crossing into the kernel and back',
  desc: 'User code cannot touch devices or page tables. The only way in is a system call, which switches the CPU to ring 0. Follow f.Read from a goroutine through the kernel, and see the cheap vDSO shortcut.',
  groups: [
    { id: 'user', label: 'User mode (ring 3)', x: 0, y: 0, w: 7, h: 2, color: 'green' },
    { id: 'kmode', label: 'Kernel mode (ring 0)', x: 0, y: 3, w: 7, h: 2, color: 'red' },
  ],
  nodes: [
    { id: 'g', label: 'Goroutine', sub: 'f.Read(buf)', x: 0, y: 0, color: 'green', info: 'Ordinary Go code. os.File.Read eventually calls syscall.Syscall(SYS_READ, fd, buf, len).' },
    { id: 'rt', label: 'Go runtime', sub: 'entersyscall', x: 2, y: 0, color: 'blue', info: 'Marks the goroutine and its M (OS thread) as in a syscall, so the scheduler knows this thread may block, then puts the syscall number in RAX and arguments in RDI, RSI, RDX.' },
    { id: 'm2', label: 'Other M takes P', sub: 'other Gs keep going', x: 4, y: 0, ghost: true, color: 'blue', info: 'If the syscall blocks, sysmon notices (after about 20 µs) and hands the P to another OS thread, so the remaining goroutines keep running.' },
    { id: 'vdso', label: 'vDSO page', sub: 'time.Now() ~20 ns', x: 0, y: 1, color: 'teal', info: 'A few read-only kernel functions, such as clock_gettime, mapped into every process. They read kernel-maintained data directly, so no mode switch is needed.' },
    { id: 'entry', label: 'syscall entry', sub: 'kernel stack, KPTI', x: 2, y: 3, color: 'red', info: 'The syscall instruction jumps to the kernel entry point in ring 0. The kernel switches to the task\'s kernel stack and, with KPTI, to the kernel page tables, which is part of why mitigations made syscalls slower.' },
    { id: 'sys', label: 'sys_read', sub: 'checks, copy_to_user', x: 4, y: 3, color: 'red', info: 'Validates the fd and every user pointer (user memory is untrusted), goes through the VFS to the file system, and copies data to the user buffer.' },
    { id: 'pc', label: 'Page cache', sub: 'hit: memcpy', x: 6, y: 3, shape: 'db', color: 'orange', info: 'Recently read file pages stay in RAM. A hit means read() is just a copy plus the mode switches, about 1 µs for small buffers.' },
    { id: 'drv', label: 'NVMe driver', sub: 'DMA, then IRQ', x: 6, y: 4, color: 'purple', info: 'On a miss the driver queues a DMA read and the thread sleeps until the completion interrupt, roughly 20 to 100 µs on NVMe.' },
  ],
  edges: [
    { from: 'g', to: 'rt', label: 'Read()' },
    { from: 'g', to: 'vdso', label: 'time.Now()' },
    { from: 'rt', to: 'm2', label: 'hand off P' },
    { from: 'rt', to: 'entry', label: 'syscall (RAX=0)' },
    { from: 'entry', to: 'sys', label: 'table[RAX]' },
    { from: 'sys', to: 'pc', label: 'lookup' },
    { from: 'pc', to: 'drv', both: true },
    { id: 'ret', from: 'sys', to: 'rt', dashed: true, label: 'sysret: n bytes' },
  ],
  steps: [
    { caption: 'The goroutine calls f.Read. Go\'s syscall wrapper calls entersyscall first, so the scheduler knows this OS thread might disappear into the kernel for a while.', flows: [{ from: 'g', to: 'rt', label: 'f.Read(buf)' }] },
    { caption: 'Syscall number 0 (read) goes in RAX and the arguments in registers. The syscall instruction switches to ring 0 and jumps to the kernel entry, which swaps to the kernel stack. A trivial syscall costs about 100 to 300 ns.', flows: [{ from: 'rt', to: 'entry', label: 'syscall' }] },
    { caption: 'The kernel dispatches through the syscall table to sys_read, then validates the fd and the user buffer. A user pointer is never trusted: copy_to_user handles bad addresses safely.', flows: [{ from: 'entry', to: 'sys', label: 'sys_read' }] },
    { caption: 'Page-cache hit: the data is already in RAM, so the kernel copies it into buf. The whole read takes about 0.5 to 2 µs for a small buffer.', flows: [{ from: 'sys', to: 'pc', label: 'lookup' }, { from: 'pc', to: 'sys', label: 'copy' }] },
    { caption: 'Miss: the driver starts a DMA read and the thread sleeps. Regular files cannot use the netpoller, so the whole OS thread blocks. sysmon sees the stuck M and hands its P to another thread so other goroutines keep running.', flows: [{ from: 'pc', to: 'drv', label: 'DMA read' }, { from: 'rt', to: 'm2', label: 'P handoff' }] },
    { caption: 'sysret returns to ring 3 with the byte count. exitsyscall tries to reacquire a P; if none is free, the goroutine goes to the global run queue and the thread parks.', flows: [{ from: 'drv', to: 'pc', label: 'IRQ: done' }, { from: 'sys', to: 'rt', label: 'n bytes' }] },
    { caption: 'Shortcut: time.Now() calls clock_gettime in the vDSO, a kernel page mapped into user space. No mode switch, about 20 ns, which is why timestamps are cheap in Go.', flows: [{ from: 'g', to: 'vdso', label: 'clock_gettime' }] },
    { caption: 'Design rule: every crossing costs, so do more per crossing. Use bufio, writev and larger reads, and epoll, io_uring or sendfile to cut syscalls. strace is heavy (ptrace); prefer perf trace or eBPF in production.', active: ['rt', 'entry', 'rt>entry', 'ret'] },
  ],
});

registerDiagram({
  id: 'ca-go-gmp',
  roadmap: 'computer-architecture', module: 5, topic: 'Kernel Threads vs Green Threads & Go\'s M:N Scheduler',
  kind: 'graph',
  title: 'Go\'s G-M-P scheduler: run queues, stealing, netpoller, handoff',
  desc: 'GOMAXPROCS=2 gives two Ps. A goroutine (G) runs only on an OS thread (M) that holds a P. Follow how Gs are created, stolen, parked on the network and rescued from blocking syscalls.',
  groups: [
    { id: 'rtg', label: 'Go runtime (user space)', x: 0, y: 0, w: 7, h: 4, color: 'blue' },
  ],
  nodes: [
    { id: 'grq', label: 'Global run queue', sub: 'every 61st tick', x: 2, y: 0, color: 'purple', info: 'Shared, lock-protected queue. Each P checks it every 61st schedule tick for fairness and whenever its local queue is empty.' },
    { id: 'p0', label: 'P0 local runq', sub: 'G3 G4 G5 + runnext', x: 0, y: 2, color: 'blue', info: 'Up to 256 Gs, lock-free for its owner. The runnext slot holds the most recently readied G so a producer/consumer pair stays hot in cache.' },
    { id: 'p1', label: 'P1 local runq', sub: 'empty', x: 4, y: 2, color: 'blue', info: 'An idle P first checks its local queue, then the global queue, then the netpoller, then tries to steal half of another P\'s queue.' },
    { id: 'np', label: 'Netpoller', sub: 'epoll: parked Gs', x: 6, y: 2, color: 'teal', info: 'One epoll instance per process. Each socket has a pollDesc that remembers the goroutine waiting on it.' },
    { id: 'm0', label: 'M0 (OS thread)', sub: 'running G1', x: 0, y: 3, color: 'green', info: 'An M executes Go code only while it holds a P. Only about GOMAXPROCS threads are running Go code at any moment.' },
    { id: 'm2', label: 'M2 (spare thread)', sub: 'takes over P0', x: 2, y: 3, ghost: true, color: 'green', enter: 6, info: 'Taken from the idle-thread list or newly created. The default limit is 10,000 threads (debug.SetMaxThreads).' },
    { id: 'm1', label: 'M1 (OS thread)', sub: 'running G2', x: 4, y: 3, color: 'green', info: 'Holds P1.' },
    { id: 'kern', label: 'Linux kernel', sub: 'schedules Ms on CPU cores', x: 0, y: 5, w: 5, color: 'gray', info: 'The kernel sees only threads. It knows nothing about goroutines, which is why a goroutine switch avoids the kernel entirely.' },
  ],
  edges: [
    { from: 'grq', to: 'p0' },
    { from: 'grq', to: 'p1', label: 'when local is empty' },
    { from: 'p0', to: 'm0', both: true },
    { from: 'p1', to: 'm1', both: true },
    { from: 'p0', to: 'p1', label: 'steal half' },
    { from: 'm1', to: 'np', label: 'park G on fd' },
    { from: 'np', to: 'p1', label: 'G runnable' },
    { from: 'p0', to: 'm2', label: 'hand off P' },
    { from: 'm0', to: 'kern', label: 'blocking read()' },
    { from: 'm2', to: 'kern' },
    { from: 'm1', to: 'kern' },
    { from: 'm0', to: 'grq', dashed: true, curve: 40, label: 'no P: G to global' },
  ],
  steps: [
    { caption: 'G1 on M0 runs go handle(c). The new goroutine G6 gets a 2 KiB stack and goes into P0\'s runnext slot. Creating it takes well under a microsecond, with no system call.', flows: [{ from: 'm0', to: 'p0', label: 'go handle(c): G6' }] },
    { caption: 'Each M runs Gs from its P. A goroutine switch saves a few registers into the g struct in user space: about 100 to 200 ns, no kernel and no TLB change.', flows: [{ from: 'p0', to: 'm0', label: 'next G' }, { from: 'p1', to: 'm1', label: 'G2' }] },
    { caption: 'G2 reads a socket with no data. read() returns EAGAIN, the runtime parks G2 on the fd\'s pollDesc, and M1 does not block: it looks for the next G.', flows: [{ from: 'm1', to: 'np', label: 'G2 parks' }] },
    { caption: 'P1\'s queue is empty. It checks the global queue, then steals half of P0\'s local queue. Work stealing keeps every P busy without a central lock on the hot path.', flows: [{ from: 'grq', to: 'p1', label: 'G7' }, { from: 'p0', to: 'p1', label: 'steal G4, G5' }] },
    { caption: 'Data arrives for G2. When a P looks for work (or sysmon polls every ~10 ms) the netpoller calls epoll_wait, and G2 becomes runnable again on a run queue.', flows: [{ from: 'np', to: 'p1', label: 'G2 ready' }] },
    { caption: 'G1 calls a blocking syscall (a file read, or cgo), and M0 is stuck in the kernel. sysmon (or entersyscallblock) hands P0 to a spare thread M2, so G3 and the rest of P0\'s queue keep running.', flows: [{ from: 'm0', to: 'kern', label: 'read(file)' }, { from: 'p0', to: 'm2', label: 'P0' }] },
    { caption: 'When the syscall returns, M0 tries to grab an idle P. If there is none, G1 goes to the global run queue and M0 parks as a spare thread.', flows: [{ from: 'm0', to: 'grq', label: 'G1' }] },
    { caption: 'Preemption: since Go 1.14 sysmon interrupts a G that has run for more than ~10 ms with a signal, so a tight loop cannot starve the others. Meanwhile the kernel still time-slices the Ms themselves onto the cores.', active: ['m1', 'm2', 'kern', 'm1>kern', 'm2>kern'] },
  ],
});

registerDiagram({
  id: 'ca-eevdf-runqueue',
  roadmap: 'computer-architecture', module: 5, topic: 'CPU Scheduling Algorithms & the Linux Scheduler',
  kind: 'graph',
  title: 'EEVDF: eligible first, then earliest virtual deadline (plus cpu.max)',
  desc: 'Since Linux 6.6 the fair scheduler is EEVDF. Each runnable task has a lag (CPU it is owed) and a virtual deadline. Watch one pick decision on a CPU, then see how a pod\'s cpu.max quota can throttle its tasks regardless of fairness.',
  groups: [
    { id: 'tasks', label: 'Runnable tasks', x: 0, y: 2, w: 1, h: 5, color: 'blue' },
    { id: 'pod', label: 'Pod cgroup', x: 3, y: 6, w: 3, h: 1, color: 'red' },
  ],
  nodes: [
    { id: 'wake', label: 'Task wakes up', sub: 'I/O done, futex', x: 0, y: 0, color: 'gray', info: 'A task that becomes runnable is placed back into the run queue with the lag it had when it went to sleep, so sleeping neither earns unlimited credit nor loses its place.' },
    { id: 'rq', label: 'CPU 3 run queue', sub: 'avg vruntime V = 100', x: 2, y: 0, w: 2, color: 'blue', info: 'Each CPU has its own run queue; the load balancer moves tasks between CPUs. V is the weighted average virtual runtime of the queue. A task\'s vruntime advances by real runtime x 1024 / weight, so heavier (lower nice) tasks age more slowly.' },
    { id: 'ta', label: 'api handler', sub: 'lag +2 · vd 101', x: 0, y: 2, color: 'green', info: 'vruntime 98, below V, so its lag is +2: it is owed CPU and is eligible. It asked for a short slice, so its virtual deadline (eligible time + slice / weight) is early.' },
    { id: 'tb', label: 'batch job', sub: 'lag −3 · vd 100', x: 0, y: 4, color: 'orange', info: 'vruntime 103: it has already had more than its fair share (lag -3), so it is NOT eligible, even though its deadline of 100 is the earliest in the queue. It must wait until V catches up.' },
    { id: 'tc', label: 'log shipper', sub: 'lag +1 · vd 104', x: 0, y: 6, color: 'green', info: 'Eligible (lag +1) but with a longer slice, so a later deadline. It runs after the api handler.' },
    { id: 'pick', label: 'pick next', sub: 'eligible, min vd', x: 3, y: 4, w: 1.25, shape: 'diamond', color: 'purple', info: 'The scheduler keeps tasks in an augmented red-black tree so it can find the eligible task with the earliest virtual deadline in O(log n).' },
    { id: 'cpu', label: 'CPU core', sub: 'runs one slice', x: 5, y: 4, color: 'green', info: 'The chosen task runs until its slice ends, it blocks, or a newly woken task with an earlier eligible deadline preempts it. The default base slice is about 3 ms.' },
    { id: 'cg', label: 'cpu.max quota', sub: '200 ms / 100 ms', x: 5, y: 6, color: 'red', info: 'Kubernetes limits.cpu: 2 becomes cpu.max "200000 100000". Runtime of every task in the pod is charged here. Requests become cpu.weight, which only matters under contention.' },
    { id: 'thr', label: 'Throttled', sub: 'until next period', x: 3, y: 6, ghost: true, color: 'red', info: 'When the quota is spent, all of the cgroup\'s tasks are taken off the run queues until the period refills, even if the CPU is idle. cpu.stat nr_throttled and throttled_usec count it.' },
  ],
  edges: [
    { from: 'wake', to: 'rq', label: 'enqueue' },
    { from: 'ta', to: 'pick' },
    { from: 'tb', to: 'pick', dashed: true, label: 'not eligible' },
    { from: 'tc', to: 'pick' },
    { from: 'pick', to: 'cpu', label: 'api handler' },
    { from: 'cpu', to: 'rq', label: 'slice used: requeue' },
    { from: 'cpu', to: 'cg', label: 'charge runtime' },
    { from: 'cg', to: 'thr', label: 'quota spent' },
  ],
  steps: [
    { caption: 'A task wakes up (its I/O completed) and is enqueued on a CPU\'s run queue. EEVDF keeps the lag it had when it slept, so it neither jumps the queue unfairly nor loses its place.', flows: [{ from: 'wake', to: 'rq', label: 'enqueue' }] },
    { caption: 'Every task\'s vruntime advances by runtime x 1024 / weight (nice 0 = 1024, each nice step about 1.25x). V is the queue\'s weighted average. Lag = V - vruntime is the CPU a task is owed.', active: ['rq', 'ta', 'tb', 'tc'] },
    { caption: 'Eligibility comes first: the batch job has lag -3, it already got more than its share, so it is skipped even though its deadline of 100 is the earliest. This is how EEVDF stays fair.', flows: [{ from: 'tb', to: 'pick', label: 'skipped', color: 'red' }] },
    { caption: 'Among eligible tasks the earliest virtual deadline wins. Deadline = eligible time + slice / weight, so the api handler, which asks for short slices, runs before the log shipper without getting more total CPU.', flows: [{ from: 'ta', to: 'pick', label: 'vd 101' }, { from: 'tc', to: 'pick', label: 'vd 104' }] },
    { caption: 'The api handler runs for its slice. A newly woken task with an earlier eligible deadline can preempt it, which is how EEVDF gives latency-sensitive tasks fast wake-ups without CFS\'s old heuristics.', flows: [{ from: 'pick', to: 'cpu', label: 'run' }] },
    { caption: 'When the slice is used up, its vruntime has advanced, its lag shrinks, it gets a new deadline and goes back into the queue. Over time every task receives CPU in proportion to its weight.', flows: [{ from: 'cpu', to: 'rq', label: 'requeue' }] },
    { caption: 'Separately, all runtime of a pod\'s tasks is charged to its cgroup. With limits.cpu: 2, a pod running 16 threads burns its 200 ms quota in about 12.5 ms of wall time.', flows: [{ from: 'cpu', to: 'cg', label: 'charge' }] },
    { caption: 'Quota spent: every task in the cgroup is throttled until the next 100 ms period, even on an idle CPU. Fairness (weights) and ceilings (cpu.max) are different mechanisms; the ceiling causes the p99 spikes.', flows: [{ from: 'cg', to: 'thr', label: 'throttle', color: 'red' }] },
  ],
});

registerDiagram({
  id: 'ca-signal-delivery',
  roadmap: 'computer-architecture', module: 5, topic: 'Signals & Inter-Process Communication',
  kind: 'sequence',
  title: 'SIGTERM to a Go pod: delivery, graceful shutdown, SIGKILL',
  desc: 'A signal is only marked pending when it is sent; it is delivered when a thread next returns to user mode. Follow a Kubernetes SIGTERM into a Go program, then see a fault-driven SIGSEGV and the SIGURG the runtime sends itself for preemption.',
  actors: [
    { id: 'kl', label: 'kubelet', sub: 'via container runtime', icon: '☸️', color: 'gray', info: 'On pod deletion the endpoints are removed and the preStop hook runs; then the container runtime sends SIGTERM to PID 1 of each container, waits terminationGracePeriodSeconds (default 30 s) and sends SIGKILL.' },
    { id: 'k', label: 'Kernel', sub: 'pending sets + masks', color: 'red', info: 'Keeps a shared pending set per process and one per thread, plus each thread\'s signal mask. Standard signals do not queue: two pending SIGCHLDs merge into one.' },
    { id: 'rt', label: 'Go runtime', sub: 'handler on every M', color: 'blue', info: 'The runtime installs its own handler for every signal on every OS thread, with an alternate signal stack. It turns faults into panics, feeds signal.Notify channels and uses SIGURG and SIGPROF internally.' },
    { id: 'g', label: 'main goroutine', sub: 'signal.NotifyContext', icon: '🧵', color: 'green', info: 'Application code waiting on ctx.Done() from signal.NotifyContext(ctx, SIGTERM, SIGINT).' },
  ],
  steps: [
    { section: 'Generate and deliver' },
    { from: 'kl', to: 'k', label: 'kill(pid, SIGTERM)', caption: 'After the preStop hook, the runtime sends SIGTERM to the container\'s PID 1. Nothing runs yet: the kernel just marks the signal pending on the process.' },
    { from: 'k', to: 'k', label: 'pick a thread', caption: 'A process-directed signal goes to any thread that does not block it. Delivery happens when that thread next returns to user mode, after a syscall, an interrupt or a reschedule; a sleeping thread is woken.' },
    { from: 'k', to: 'rt', label: 'run handler', caption: 'The kernel pushes a signal frame onto the thread\'s signal stack and jumps to the runtime\'s handler. An interrupted blocking syscall returns EINTR or is restarted.' },
    { from: 'rt', to: 'rt', label: 'queue for Notify', caption: 'The handler only records the signal, because almost nothing is safe to do inside a handler. A runtime goroutine forwards it to registered channels with a non-blocking send.' },
    { from: 'rt', to: 'g', label: 'ctx.Done() closes', caption: 'signal.NotifyContext cancels its context. Without any Notify, the Go runtime would exit immediately on SIGTERM, skipping graceful shutdown.' },
    { section: 'Graceful shutdown' },
    { from: 'g', to: 'g', label: 'readiness = 503', caption: 'Fail readiness first so remaining load balancers and kube-proxy rules stop sending new requests during the few seconds they take to update.' },
    { from: 'g', to: 'g', label: 'srv.Shutdown(ctx)', caption: 'Close listeners, let in-flight requests finish, stop workers via context, flush buffers. Budget it well inside the grace period.' },
    { from: 'g', to: 'k', label: 'exit(0)', caption: 'A clean exit before the deadline: the kubelet records a normal termination and nothing is lost.' },
    { section: 'Too slow: grace period expires' },
    { from: 'kl', to: 'k', label: 'kill(pid, SIGKILL)', caption: 'If the process is still alive after terminationGracePeriodSeconds, the runtime sends SIGKILL.' },
    { from: 'k', to: 'g', label: 'killed, no handler runs', reply: true, caption: 'SIGKILL and SIGSTOP can never be caught, blocked or ignored. The kernel tears the process down at once: no defers, exit code 137. A task in D state dies only when its I/O finishes.' },
    { section: 'Synchronous signal: a fault' },
    { from: 'g', to: 'k', label: 'load from nil → #PF', caption: 'A nil pointer dereference touches page 0, which is never mapped. The page fault has no valid VMA.' },
    { from: 'k', to: 'rt', label: 'SIGSEGV to this thread', caption: 'Synchronous signals always go to the faulting thread, never to an arbitrary one.' },
    { from: 'rt', to: 'g', label: 'panic: nil pointer', caption: 'The runtime sees a fault near address 0 in Go code and turns it into a run-time panic that defer and recover can see.' },
    { section: 'The runtime signals itself' },
    { from: 'rt', to: 'k', label: 'tgkill(M, SIGURG)', caption: 'Since Go 1.14, sysmon preempts a goroutine that has run for more than about 10 ms by sending SIGURG to its thread. SIGPROF drives the CPU profiler the same way.' },
    { from: 'k', to: 'rt', label: 'handler on that M', caption: 'The handler parks the running goroutine at a safe point so others, and the GC, can run. Side effect: more EINTR in syscalls and cgo code, which Go\'s own wrappers retry.' },
  ],
});

