registerDiagram({
  id: 'ca-go-mutex',
  roadmap: 'computer-architecture', module: 6, topic: 'Mutexes, Spinlocks & Reader-Writer Locks',
  kind: 'graph',
  title: 'Inside sync.Mutex: CAS fast path, spin, park, starvation mode',
  desc: 'sync.Mutex is an adaptive lock: one atomic instruction when nobody competes, a short spin when the holder is likely to finish soon, and sleeping in the runtime otherwise. A 1 ms rule keeps waiters from starving.',
  nodes: [
    { id: 'lock', label: 'mu.Lock()', x: 0, y: 0, shape: 'pill', color: 'gray', info: 'Called by any goroutine. sync.Mutex is not reentrant: locking it twice from one goroutine deadlocks.' },
    { id: 'cas', label: 'CAS 0 → 1 ok?', x: 2, y: 0, shape: 'diamond', color: 'yellow', info: 'A single LOCK CMPXCHG on the state word, about 10 to 25 ns when uncontended. The state word also holds the woken and starving flags and the waiter count.' },
    { id: 'held', label: 'Lock held', sub: 'fast path ~10–25 ns', x: 4, y: 0, shape: 'pill', color: 'green', info: 'The caller owns the mutex. Keep what follows short.' },
    { id: 'crit', label: 'Critical section', sub: 'no I/O inside', x: 6, y: 0, color: 'green', info: 'Never do I/O or call unknown code while holding a lock. Put the mutex next to the data it guards.' },
    { id: 'spinq', label: 'Spin allowed?', x: 2, y: 2, shape: 'diamond', color: 'yellow', info: 'Only if the machine is multicore, GOMAXPROCS > 1, at least one other P is running, the local run queue is empty, and fewer than 4 spin rounds have been done.' },
    { id: 'spin', label: 'Spin briefly', sub: '~30 PAUSE, ≤4 rounds', x: 0, y: 2, color: 'orange', info: 'Busy-waiting for a few hundred nanoseconds is cheaper than sleeping and waking if the holder is about to release.' },
    { id: 'park', label: 'Park goroutine', sub: 'runtime semaphore', x: 2, y: 4, color: 'purple', info: 'The goroutine sleeps in a runtime semaphore queue. Only the goroutine parks: the OS thread runs other goroutines. In C, the equivalent is a futex syscall that puts the thread to sleep.' },
    { id: 'starve', label: 'Waited >1 ms?', x: 4, y: 2, shape: 'diamond', color: 'yellow', info: 'If a woken waiter has waited more than 1 ms in total, the mutex switches to starvation mode.' },
    { id: 'unlock', label: 'mu.Unlock()', sub: 'atomic add, wake one', x: 4, y: 4, color: 'blue', info: 'Clears the locked bit with one atomic operation. If waiters exist, it wakes one (normal mode) or hands ownership directly to the first one (starvation mode).' },
  ],
  edges: [
    { from: 'lock', to: 'cas' },
    { from: 'cas', to: 'held', label: 'yes' },
    { from: 'held', to: 'crit' },
    { from: 'cas', to: 'spinq', label: 'no: contended' },
    { from: 'spinq', to: 'spin', label: 'yes' },
    { from: 'spin', to: 'cas', label: 'retry' },
    { from: 'spinq', to: 'park', label: 'no' },
    { from: 'crit', to: 'unlock', label: 'done' },
    { from: 'unlock', to: 'park', label: 'wake waiter' },
    { from: 'park', to: 'starve', label: 'woken' },
    { from: 'starve', to: 'cas', label: 'no: compete' },
    { from: 'starve', to: 'held', label: 'yes: FIFO handoff' },
  ],
  steps: [
    { caption: 'Uncontended: one compare-and-swap flips the state from 0 to locked, about 10 to 25 ns. No kernel, no scheduler. Most locks in a healthy service take this path almost every time.', flows: [{ from: 'lock', to: 'cas', label: 'Lock()' }, { from: 'cas', to: 'held', label: '0 → 1' }] },
    { caption: 'Contended: the CAS fails because another goroutine holds the lock. Before sleeping, the mutex checks whether spinning makes sense.', flows: [{ from: 'cas', to: 'spinq', label: 'locked' }] },
    { caption: 'Spin only if other Ps are running (so the holder is likely on a CPU and about to finish) and the local run queue is empty. A few rounds of PAUSE, then retry the CAS. On a single core, spinning is pointless.', flows: [{ from: 'spinq', to: 'spin', label: 'spin' }, { from: 'spin', to: 'cas', label: 'retry CAS' }] },
    { caption: 'Still locked: the goroutine parks on a runtime semaphore. Only the goroutine sleeps; its OS thread runs other goroutines. A user-space spinlock would instead burn whole time slices if the holder got preempted.', flows: [{ from: 'spinq', to: 'park', label: 'sleep' }] },
    { caption: 'The holder finishes its critical section and calls Unlock, which clears the bit atomically. Waiters exist, so it wakes one.', flows: [{ from: 'held', to: 'crit', label: 'work' }, { from: 'crit', to: 'unlock', label: 'Unlock()' }, { from: 'unlock', to: 'park', label: 'wake 1' }] },
    { caption: 'Normal mode: the woken waiter must compete with newly arriving goroutines, which are already running on a CPU and usually win the CAS. Letting them barge in gives better throughput.', flows: [{ from: 'park', to: 'starve', label: 'woken' }, { from: 'starve', to: 'cas', label: 'compete' }] },
    { caption: 'Starvation mode: a waiter that has waited more than 1 ms flips the mutex into FIFO mode. Unlock hands ownership straight to the first waiter, and newcomers queue at the tail without spinning. It switches back when the queue drains.', flows: [{ from: 'park', to: 'starve', label: '> 1 ms' }, { from: 'starve', to: 'held', label: 'handoff' }] },
    { caption: 'Rules: keep critical sections short, never do I/O under a lock, use defer mu.Unlock(). RWMutex readers still contend on a shared counter, so for tiny sections a plain Mutex is often faster; for read-mostly config, swap an atomic.Pointer to an immutable snapshot.', active: ['crit', 'cas'] },
  ],
});

registerDiagram({
  id: 'ca-store-buffer',
  roadmap: 'computer-architecture', module: 6, topic: 'Memory Ordering, Barriers & the Go Memory Model',
  kind: 'graph',
  title: 'The store-buffer litmus test: how r1 == r2 == 0 happens on x86',
  desc: 'x = y = 0. T1 runs x = 1; r1 = y. T2 runs y = 1; r2 = x. No interleaving of these four lines gives r1 == r2 == 0, yet real x86 hardware produces it. The store buffer is why.',
  groups: [
    { id: 'k0', label: 'Core 0', x: 0, y: 0, w: 1, h: 3, color: 'blue' },
    { id: 'k1', label: 'Core 1', x: 5, y: 0, w: 1, h: 3, color: 'blue' },
  ],
  nodes: [
    { id: 't1', label: 'T1', sub: 'x = 1; r1 = y', x: 0, y: 0, color: 'blue', info: 'Goroutine or thread 1, running on core 0.' },
    { id: 'sb0', label: 'Store buffer 0', sub: 'pending: x = 1', x: 0, y: 2, color: 'orange', info: 'A FIFO of retired stores waiting to be written to L1. It lets the core keep going while it waits for cache-line ownership. A core sees its own buffered stores (store-to-load forwarding), but other cores cannot.' },
    { id: 't2', label: 'T2', sub: 'y = 1; r2 = x', x: 5, y: 0, color: 'blue', info: 'Goroutine or thread 2, running on core 1.' },
    { id: 'sb1', label: 'Store buffer 1', sub: 'pending: y = 1', x: 5, y: 2, color: 'orange', info: 'Core 1\'s private store buffer.' },
    { id: 'mem', label: 'Coherent caches', sub: 'x = 0, y = 0', x: 2, y: 4, w: 2, shape: 'db', color: 'teal', info: 'L1, L2, L3 and memory, kept coherent by MESI. Coherence guarantees one order of writes per location; it does not stop a core from reordering its own store and a later load.' },
  ],
  edges: [
    { from: 't1', to: 'sb0', label: 'store' },
    { from: 't2', to: 'sb1', label: 'store' },
    { from: 'sb0', to: 'mem', label: 'drains later' },
    { from: 'sb1', to: 'mem', label: 'drains later' },
    { id: 'ld0', from: 't1', to: 'mem', label: 'load y' },
    { id: 'ld1', from: 't2', to: 'mem', label: 'load x' },
  ],
  steps: [
    { caption: 'T1 executes x = 1. The store retires into core 0\'s store buffer instead of waiting tens of nanoseconds to gain ownership of the cache line.', flows: [{ from: 't1', to: 'sb0', label: 'x = 1' }] },
    { caption: 'At the same time T2 executes y = 1, which also sits in its own store buffer. Neither store is visible to the other core yet.', flows: [{ from: 't2', to: 'sb1', label: 'y = 1' }] },
    { caption: 'T1 loads y. Loads do not wait for older stores to other addresses, so it reads the cache, where y is still 0. r1 = 0.', flows: [{ from: 'mem', to: 't1', label: 'y → 0' }], active: ['ld0'] },
    { caption: 'T2 loads x and also reads the old value. r2 = 0. Each core\'s store was effectively reordered after its later load.', flows: [{ from: 'mem', to: 't2', label: 'x → 0' }], active: ['ld1'] },
    { caption: 'Only now do the buffers drain. Both writes become visible, too late. x86 (TSO) allows exactly this one reordering, store then later load. ARM64 and POWER allow load-load, load-store and store-store reordering too.', flows: [{ from: 'sb0', to: 'mem', label: 'x = 1' }, { from: 'sb1', to: 'mem', label: 'y = 1' }] },
    { caption: 'The fix is a full barrier between the store and the load, such as MFENCE or a LOCK-prefixed instruction, which drains the store buffer first. Go\'s atomic.Store on amd64 uses XCHG, which is implicitly locked, so atomics are sequentially consistent.', active: ['sb0', 'sb1', 't1', 't2'] },
    { caption: 'In Go you never write fences. Use channels, mutexes, sync.Once or sync/atomic, which create happens-before edges. A data-race-free program behaves as if sequentially consistent (DRF-SC). Double-checked locking on a plain bool is broken: use sync.Once.', active: ['t1', 't2', 'mem'] },
  ],
});

registerDiagram({
  id: 'ca-deadlock-lock-order',
  roadmap: 'computer-architecture', module: 6, topic: 'Deadlock, Livelock, Starvation & Priority Inversion',
  kind: 'graph',
  title: 'A transfer deadlock: the wait-for cycle and the lock-ordering fix',
  desc: 'Two goroutines transfer money in opposite directions and lock the two accounts in opposite orders. Watch the wait-for cycle form, map it to the four Coffman conditions, then break circular wait with a global lock order.',
  groups: [
    { id: 'wfg', label: 'Wait-for graph', x: 0, y: 0, w: 7, h: 3, color: 'blue' },
    { id: 'coff', label: 'Coffman conditions: all four needed', x: 0, y: 4, w: 7, h: 1, color: 'purple' },
  ],
  nodes: [
    { id: 'g1', label: 'G1', sub: 'transfer(A → B)', x: 0, y: 1, color: 'green', info: 'Locks the source account, then the destination. Correct in isolation; deadlock needs a second goroutine doing the opposite.' },
    { id: 'la', label: 'Mutex A', sub: 'account 17', x: 3, y: 0, shape: 'pill', color: 'orange', info: 'A sync.Mutex guarding account 17\'s balance. Not reentrant and not preemptible: nobody can take it away from its holder.' },
    { id: 'lb', label: 'Mutex B', sub: 'account 42', x: 3, y: 2, shape: 'pill', color: 'orange', info: 'A sync.Mutex guarding account 42\'s balance.' },
    { id: 'g2', label: 'G2', sub: 'transfer(B → A)', x: 6, y: 1, color: 'green', info: 'The same code with the arguments swapped, so it locks B first, then A.' },
    { id: 'c1', label: 'Mutual exclusion', sub: 'one holder', x: 0, y: 4, color: 'purple', info: 'Break it with data nobody needs to lock: immutable snapshots, atomics, or a single goroutine that owns the balances and receives requests on a channel.' },
    { id: 'c2', label: 'Hold and wait', sub: 'keep A, want B', x: 2, y: 4, color: 'purple', info: 'Break it by acquiring everything at once, or with TryLock: if the second lock is busy, release the first and retry after a jittered backoff (beware livelock without jitter).' },
    { id: 'c3', label: 'No preemption', sub: 'cannot steal a lock', x: 4, y: 4, color: 'purple', info: 'Break it with timeouts that force a release: context deadlines on lock-like waits, database lock timeouts, or leases in distributed locks.' },
    { id: 'c4', label: 'Circular wait', sub: 'G1 → G2 → G1', x: 6, y: 4, color: 'red', info: 'The cheapest condition to break: impose one global order (by account ID, by address, or by a lock hierarchy level) and always acquire in that order.' },
    { id: 'dump', label: 'Goroutine dump', sub: 'debug=2 or SIGQUIT', x: 0, y: 6, color: 'gray', info: 'The runtime only reports a global deadlock (all goroutines asleep). A partial deadlock in a server just hangs requests; /debug/pprof/goroutine?debug=2 shows goroutines stuck in sync.Mutex.Lock for minutes.' },
    { id: 'fix', label: 'Global lock order', sub: 'lower ID first', x: 6, y: 6, color: 'green', enter: 7, info: 'Both transfers lock account 17 before account 42, whatever the direction. A cycle can no longer form, so deadlock is impossible. Handle from == to separately.' },
  ],
  edges: [
    { from: 'g1', to: 'la', label: 'holds' },
    { from: 'g1', to: 'lb', dashed: true, label: 'waits for' },
    { from: 'g2', to: 'lb', label: 'holds' },
    { from: 'g2', to: 'la', dashed: true, label: 'waits for' },
    { from: 'c4', to: 'fix', label: 'break this one' },
  ],
  steps: [
    { caption: 'G1 starts transfer(A, B) and locks account A. Locking the source first looks perfectly reasonable.', flows: [{ from: 'g1', to: 'la', label: 'Lock()' }] },
    { caption: 'At the same moment G2 starts transfer(B, A) and locks account B. Each goroutine now holds one lock.', flows: [{ from: 'g2', to: 'lb', label: 'Lock()' }] },
    { caption: 'G1 asks for B and blocks: G2 holds it. Still fine if G2 finishes soon.', flows: [{ from: 'g1', to: 'lb', label: 'Lock() blocks', color: 'red' }] },
    { caption: 'G2 asks for A and blocks: G1 holds it. Now G1 waits for G2 and G2 waits for G1. A cycle in the wait-for graph means deadlock; neither will ever run again.', flows: [{ from: 'g2', to: 'la', label: 'Lock() blocks', color: 'red' }], active: ['g1>la', 'g1>lb', 'g2>lb', 'g2>la'] },
    { caption: 'All four Coffman conditions hold: exclusive locks, each holds one while waiting for another, locks cannot be taken away, and the waits form a cycle. Remove any one and deadlock is impossible.', active: ['c1', 'c2', 'c3', 'c4'] },
    { caption: 'Go reports "all goroutines are asleep" only if the whole program is stuck. In a server, other goroutines keep running, so you see hung requests; a goroutine dump shows both stuck in sync.Mutex.Lock.', active: ['dump', 'g1', 'g2'] },
    { caption: 'The practical fix breaks circular wait: always lock the account with the lower ID first. Lock ordering is what kernels, databases and most production code rely on.', active: ['c4', 'c4>fix'] },
    { caption: 'With the order in place, G2 also locks A first, so it waits for G1 before holding anything. G1 finishes and G2 proceeds: no cycle can form.', flows: [{ from: 'g2', to: 'la', label: 'Lock A first' }], active: ['fix'] },
    { caption: 'Other options break other conditions: TryLock with jittered backoff (hold and wait), timeouts (no preemption), one goroutine owning all balances (mutual exclusion). Databases instead detect the cycle and abort one transaction.', active: ['c1', 'c2', 'c3'] },
  ],
});

