registerDiagram({
  id: 'ca-netpoller',
  roadmap: 'computer-architecture', module: 7, topic: 'How Go\'s Netpoller Uses epoll',
  kind: 'sequence',
  title: 'conn.Read in Go: blocking code on top of epoll',
  desc: 'You write a blocking read in one goroutine per connection; the runtime turns it into non-blocking I/O plus edge-triggered epoll. Only the goroutine waits, never the OS thread.',
  actors: [
    { id: 'g', label: 'Goroutine G1', sub: 'n, err := conn.Read', icon: '🧵', color: 'green', info: 'Handler code with one goroutine per connection. It looks blocking, but the runtime makes it cheap: about 2 to 8 KiB of stack per idle connection.' },
    { id: 'rt', label: 'Go scheduler', sub: 'P + M + netpoll', color: 'blue', info: 'Parks and readies goroutines. The netpoller is part of the runtime and wraps one epoll instance per process (kqueue on macOS, IOCP on Windows).' },
    { id: 'k', label: 'Kernel', sub: 'socket + eventpoll', color: 'red', info: 'The eventpoll object holds a red-black tree of registered fds and a ready list. A callback on the socket\'s wait queue adds the fd to the ready list when data arrives.' },
    { id: 'nic', label: 'NIC', sub: 'DMA + interrupt', icon: '🔌', color: 'gray', info: 'Writes packets into RAM by DMA and raises an interrupt; NAPI then polls the ring and the TCP stack queues the data on the socket.' },
  ],
  steps: [
    { section: 'Once per socket' },
    { from: 'rt', to: 'k', label: 'epoll_ctl ADD, ET', caption: 'When net accepts or dials a connection, the fd is set non-blocking and registered once for EPOLLIN, EPOLLOUT and EPOLLRDHUP, edge-triggered. No re-arming is needed afterwards.' },
    { section: 'Read with no data yet' },
    { from: 'g', to: 'k', label: 'read(fd, buf)', caption: 'conn.Read first just tries the read(2) syscall. If data is already buffered it returns immediately, with no epoll involved.' },
    { from: 'k', to: 'g', label: 'EAGAIN', reply: true, caption: 'The socket buffer is empty, and a non-blocking socket says so instead of sleeping.' },
    { from: 'g', to: 'rt', label: 'gopark on pollDesc', caption: 'The goroutine records itself in the fd\'s pollDesc and parks. The OS thread is not blocked.' },
    { from: 'rt', to: 'rt', label: 'run other Gs', caption: 'The M picks the next runnable goroutine. 100K idle connections cost 100K small stacks, but only about GOMAXPROCS busy threads.' },
    { section: 'Data arrives' },
    { from: 'nic', to: 'k', label: 'DMA + IRQ', caption: 'The packet lands in RAM via DMA and the TCP stack queues the payload on the socket.' },
    { from: 'k', to: 'k', label: 'fd → ready list', caption: 'The socket\'s wait-queue callback adds the fd to the epoll ready list. With edge triggering it is reported once per new arrival.' },
    { from: 'rt', to: 'k', label: 'epoll_wait (netpoll)', caption: 'The scheduler polls without blocking when it looks for work, blocks in epoll_wait when an M has nothing else to do, and sysmon polls if nobody has for about 10 ms.' },
    { from: 'k', to: 'rt', label: 'ready: fd 7', reply: true, caption: 'epoll returns only ready fds, O(ready), not O(all connections) like select or poll.' },
    { from: 'rt', to: 'g', label: 'G1 runnable', caption: 'The fd maps back to its pollDesc, which names the parked goroutine. G1 goes onto a run queue.' },
    { from: 'g', to: 'k', label: 'read(fd, buf) again', caption: 'G1 resumes inside conn.Read and retries read(2).' },
    { from: 'k', to: 'g', label: 'n = 1448 bytes', reply: true, caption: 'This time it succeeds. Your code saw one blocking call; underneath it was two syscalls, a park and a wake-up.' },
    { section: 'Deadlines' },
    { from: 'rt', to: 'g', label: 'deadline timer fires', caption: 'SetReadDeadline (used by http.Server timeouts) attaches a runtime timer to the pollDesc. If it fires first, the parked goroutine wakes with os.ErrDeadlineExceeded.' },
  ],
});

registerDiagram({
  id: 'ca-zero-copy',
  roadmap: 'computer-architecture', module: 7, topic: 'File Descriptors, the Page Cache, fsync & Zero-Copy',
  kind: 'graph',
  title: 'Serving a file: read + write vs sendfile (zero-copy)',
  desc: 'Sending a file to a socket with read() and write() moves every byte four times and crosses into the kernel twice. sendfile() keeps the data in the kernel. Watch both paths.',
  groups: [
    { id: 'us', label: 'User space', x: 0, y: 0, w: 7, h: 1, color: 'green' },
    { id: 'ks', label: 'Kernel', x: 0, y: 2, w: 7, h: 1, color: 'red' },
    { id: 'hw', label: 'Hardware', x: 0, y: 4, w: 7, h: 1, color: 'gray' },
  ],
  nodes: [
    { id: 'app', label: 'Go app', sub: 'file server', x: 0, y: 0, color: 'green', info: 'A naive loop does n := f.Read(buf); conn.Write(buf[:n]). io.Copy(conn, file) does better automatically.' },
    { id: 'ubuf', label: 'User buffer', sub: 'buf []byte', x: 3, y: 0, color: 'green', info: 'Exists only so the data can pass through user space. For a plain file server, that trip is pure overhead.' },
    { id: 'pc', label: 'Page cache', sub: 'file pages', x: 1, y: 2, shape: 'db', color: 'orange', info: 'File data cached in RAM. A hot file is served from here without touching the disk at all.' },
    { id: 'sock', label: 'Socket buffer', sub: 'TCP send queue', x: 5, y: 2, color: 'orange', info: 'Data waiting to be segmented and sent. With sendfile on a scatter-gather NIC it holds only references to page-cache pages.' },
    { id: 'disk', label: 'NVMe SSD', sub: 'file blocks', x: 0, y: 4, shape: 'db', color: 'purple', info: 'Read by DMA into the page cache on a cache miss.' },
    { id: 'nic', label: 'NIC', sub: 'scatter-gather DMA', x: 6, y: 4, color: 'purple', info: 'A NIC that supports scatter-gather DMA can collect packet data from several memory locations, so it can read straight from page-cache pages.' },
  ],
  edges: [
    { from: 'disk', to: 'pc', label: 'DMA' },
    { from: 'pc', to: 'ubuf', label: 'CPU copy 1' },
    { from: 'ubuf', to: 'sock', label: 'CPU copy 2' },
    { from: 'sock', to: 'nic', label: 'DMA' },
    { from: 'pc', to: 'sock', dashed: true, label: 'page references' },
    { from: 'pc', to: 'nic', dashed: true, curve: 40, label: 'sendfile: DMA gather' },
    { from: 'app', to: 'ubuf', label: 'read / write' },
  ],
  steps: [
    { caption: 'read(file, buf): the first mode switch into the kernel. If the pages are not cached, the SSD DMAs them into the page cache with no CPU copying.', flows: [{ from: 'app', to: 'ubuf', label: 'read()' }, { from: 'disk', to: 'pc', label: 'DMA' }] },
    { caption: 'The kernel copies the data from the page cache into your buffer: CPU copy 1. read() returns, the second mode switch.', flows: [{ from: 'pc', to: 'ubuf', label: 'copy_to_user' }] },
    { caption: 'write(sock, buf): the third mode switch. The kernel copies the same bytes back from your buffer into the socket buffer: CPU copy 2.', flows: [{ from: 'app', to: 'ubuf', label: 'write()' }, { from: 'ubuf', to: 'sock', label: 'copy_from_user' }] },
    { caption: 'The NIC DMAs from the socket buffer and write() returns: the fourth mode switch. Per chunk: 4 copies (2 by the CPU), 2 syscalls, and both CPU copies push useful data out of the caches.', flows: [{ from: 'sock', to: 'nic', label: 'DMA' }] },
    { caption: 'sendfile(sock, file): one syscall, and the data never enters user space. The kernel appends references to the page-cache pages to the socket, not the bytes themselves.', flows: [{ from: 'pc', to: 'sock', label: 'page refs' }], active: ['app'] },
    { caption: 'The scatter-gather NIC DMAs straight from the page cache: zero CPU copies and two mode switches. Kafka serves consumers this way and nginx uses sendfile on.', flows: [{ from: 'pc', to: 'nic', label: 'DMA gather' }] },
    { caption: 'In Go, io.Copy(tcpConn, file) uses sendfile and io.Copy(tcpConn, tcpConn) uses splice on Linux, automatically. TLS breaks zero-copy because the bytes must be encrypted, unless the kernel does it (kTLS).', active: ['app', 'pc', 'nic', 'pc>nic'] },
  ],
});

